COLLNT("muwattaansar",{"436":["§خلاصۃ الباب","اس باب میں دو روایات ہیں، ایک موقوف (اثر صحابی رضی اللہ عنہ) اور ایک مقطوع (اثر تابعی رحمہ اللہ) اور دونوں سنداً صحیح ہیں۔"],"437":["§خلاصۃ الباب","اس باب میں کوئی روایت نہیں ہے، البتہ امام مالک رحمہ اللہ کے پانچ فتاویٰ جات مذکور ہیں۔","۔۔۔۔۔ امام مالک رحمہ اللہ کے نزدیک مدبر غلام کو صرف اس صورت میں بیچ سکتے ہیں کہ میت مقروض ہو اور قرض اس کے سارے مال پر محیط ہو اور مکمل غلام کو یا اس کے کچھ حصے کو بیچے بغیر ادائیگی نہ ہو سکتی ہو۔۔۔۔۔ امام شافعی رحمہ اللہ اور اہلحدیث کے نزدیک آقا کی کسی بھی مجبوری، محتاجی اور ضرورت کے موقع پر اسے بیچنا جائز ہے بشرطیکہ اس مدبر غلام کے سوا اور کوئی مال نہ ہو، جبکہ امام ابو حنیفہ رحمہ اللہ کے نزدیک اسے کسی بھی صورت میں بیچنا جائز نہیں۔ سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ «أَنَّ رَجُلاً أَعْتَقَ غُلَاماً لَهُ عَنْ دُبُرٍ فَاحْتَاجَ فَأَخَذَهُ النَّبِيُّ صلی اللہ علیہ وسلم، فَقَالَ مَنْ يَشْتَرِيهِ مِنِّي فَاشْتَرَاهُ نُعَيْمُ بْنُ عَبْدِ اللهِ» ‘‘ بے شک ایک (انصاری) آدمی نے اپنے غلام کو مدبر بنا کر آزاد کر دیا پھر وہ محتاج ہو گیا، تو نبی اکرم صلی اللہ علیہ وسلم نے اس غلام کو لے لیا اور فرمایا: ’’کون مجھ سے اسے خریدے گا؟‘‘ تو سیدنا نعیم بن عبد اللہ رضی اللہ عنہ نے اسے خرید لیا۔‘‘ (بخاری: ۲۱۴۱، مسلم: ۹۹۷) ایک روایت میں ہے کہ اس مدبر غلام کے سوا اور کوئی مال نہ تھا اور سیدنا نعیم رضی اللہ عنہ نے اسے آٹھ سو درہم میں خریدا تھا، وہ ایک قبطی (مصری) غلام تھا۔ (بخاری: ۶۷۱۶) لہٰذا یہی راجح ہے کہ مدبر غلام کو بیچا جا سکتا ہے لیکن شدید ضرورت و احتیاج ہی کے وقت۔","قَالَ مَالِكٌ : الْأَمْرُ الْمُجْتَمَعُ عَلَيْهِ عِنْدَنَا فِي الْمُدَبَّرِ : أَنَّ صَاحِبَهُ لَا يَبِيعُهُ ، وَلَا يُحَوِّلُهُ عَنْ مَوْضِعِهِ الَّذِي وَضَعَهُ فِيهِ ، وَأَنَّهُ إِنْ رَهِقَ سَيِّدَهُ دَيْنٌ ، فَإِنَّ غُرَمَاءَهُ لَا يَقْدِرُونَ عَلَى بَيْعِهِ مَا عَاشَ سَيِّدُهُ ، فَإِنْ مَاتَ سَيِّدُهُ وَلَا دَيْنَ عَلَيْهِ ، فَهُوَ فِي ثُلُثِهِ ، لِأَنَّهُ اسْتَثْنَى عَلَيْهِ عَمَلَهُ مَا عَاشَ ، فَلَيْسَ لَهُ أَنْ يَخْدُمَهُ حَيَاتَهُ، ثُمَّ يُعْتِقَهُ عَلَى وَرَثَتِهِ إِذَا مَاتَ مِنْ رَأْسِ مَالِهِ وَإِنْ مَاتَ سَيِّدُ الْمُدَبَّرِ وَلَا مَالَ لَهُ غَيْرُهُ عَتَقَ ثُلُثُهُ، وَكَانَ ثُلُثَاهُ لِوَرَثَتِهِ ، فَإِنْ مَاتَ سَيِّدُ","امام مالک رحمہ اللہ نے فرمایا: ہمارے ہاں مدبر غلام کے متعلق اس حکم پر اجماع ہے کہ اس کا مالک اسے بیچ نہیں سکتا اور جس جگہ اس نے اسے رکھ دیا ہے وہاں سے اسے منتقل بھی نہیں کر سکتا (یعنی ہبہ یا صدقہ کر کے اس کی ملکیت بھی تبدیل نہیں کر سکتا) اور بلاشبہ اگر اس کے آقا کو قرض ڈھانپ لے تو یقیناً اس کے قرض خواہ، جب تک اس کا آقا زندہ ہے اس (مدبر) کو بیچنے پر قدرت نہیں پا سکتے۔ (حالانکہ رسول اللہ صلی اللہ علیہ وسلم نے انصاری صحابی رضی اللہ عنہ کے مدبر غلام کو اس کی زندگی ہی میں فروخت کروایا تھا، مترجم) پھر اگر اس کا آقا مر جائے اس حال میں کہ اس پر کوئی قرض نہ الْمُدَبَّرِ، وَعَلَيْهِ دَيْنٌ مُحِيطٌ بِالْمُدَبَّرِ، بِيعَ فِي دَيْنِهِ، لِأَنَّهُ إِنَّمَا يَعْتِقُ فِي الثُّلُثِ . قَالَ : فَإِنْ كَانَ الدَّيْنُ لَا يُحِيطُ إِلَّا بِنِصْفِ الْعَبْدِ, بِيعَ نِصْفُهُ لِلدَّيْنِ، ثُمَّ عَتَقَ ثُلُثُ مَا بَقِيَ بَعْدَ الدَّيْنِ ہو تو وہ غلام اس کے تہائی مال میں سے آزاد ہوگا۔ (میت کے کل مال میں سے اسے آزاد نہیں کریں گے بلکہ ورثاء کے لیے دو تہائی مال چھوڑ کر میت کے لیے مخصوص ایک تہائی حصے کا حساب کریں گے) کیونکہ بلاشبہ اس (آقا) نے غلام پر اس کے عمل کا استثناء کر رکھا تھا جب تک کہ آقا زندہ رہے (یعنی آزاد تو کر دیا تھا لیکن یہ استثناء اور شرط بھی ساتھ شامل تھی کہ میری زندگی میں تو میرا کام اور خدمت کرتا رہے گا، گویا اس نے آزاد کر کے اُخروی ثواب بھی کمانا چاہا اور خدمت کروا کر دنیوی مفاد بھی پانا چاہا) تو اس کے لیے یہ جائز نہیں کہ اپنی زندگی میں اس سے خدمت (خود) لیتا رہے، پھر جب فوت ہو تو اپنے رأس المال (یعنی مکمل مال) میں سے اپنے ورثاء پر (یعنی ورثاء کا حق بننے والے مالی وراثت سے) اسے آزاد کرے، (تو یہ قطعاً درست نہیں کہ خود تو زندگی بھر نفع اٹھا لے اور جب مرنے لگے تو ورثاء کے حصوں پر بوجھ ڈال کر ان کا نقصان کرے)۔۔۔۔۔ اور اگر مدبر غلام کا آقا اس حال میں مر جائے کہ اس کے پاس اس کے علاوہ کچھ مال نہ ہو تو اس کا ایک تہائی حصہ آزاد ہو جائے گا اور اس کے دو تہائی حصے آقا کے ورثاء کے لیے ہوں گے۔۔۔۔۔ پھر اگر مدبر کا آقا اس حال میں مرے کہ اس پر (اس قدر) قرض ہو جو مدبر غلام کو بھی گھیر لے تو اس مدبر کو میت کے قرض (کی ادائیگی کے سلسلے) میں بیچ دیا جائے گا، کیونکہ بلاشبہ غلام تو تہائی مال میں سے آزاد ہوتا ہے (بشرطیکہ تہائی مال ہو اور اگر مال ہی نہ ہو تو نہ اس کا تہائی ہوگا اور نہ اس کا غلام آزاد ہوگا)۔ امام مالک رحمہ اللہ نے فرمایا: پھر اگر وہ قرض اس غلام کے صرف نصف حصے کو محیط ہو (آدھا غلام بیچنا پڑے) تو اس کا نصف حصہ قرضے (کے سلسلے) میں بیچا جائے گا، پھر قرض کی ادائیگی کے بعد غلام کے باقی ماندہ حصے میں سے تیسرا حصہ آزاد ہو جائے گا۔","۔۔۔۔۔ مثلاً غلام کی قیمت چھ ہزار ہو اور نصف قیمت قرض کی ادائیگی میں چلی جائے تو گویا باقی تین ہزار میت کا بچا ہوا مال ہے جس میں سے تیسرا حصہ میت کا حق ہے اور دو حصے ورثاء کا حق ہیں، لہٰذا تین ہزار میں سے ایک ہزار آزاد ہوگا جو کہ باقی ماندہ غلام کا ثلث (ایک تہائی) ہے اور مکمل غلام کا سدس (چھٹا حصہ) ہے۔","قَالَ مَالِكٌ : لَا يَجُوزُ بَيْعُ الْمُدَبَّرِ ، وَلَا يَجُوزُ لِأَحَدٍ أَنْ يَشْتَرِيَهُ ، إِلَّا أَنْ يَشْتَرِيَ الْمُدَبَّرُ نَفْسَهُ مِنْ سَيِّدِهِ ، فَيَكُونُ ذَلِكَ جَائِزاً لَهُ ، أَوْ يُعْطِيَ أَحَدٌ سَيِّدَ الْمُدَبَّرِ, مَالاً وَيُعْتِقُهُ سَيِّدُهُ الَّذِي دَبَّرَهُ، فَذَلِكَ يَجُوزُ لَهُ أَيْضاً.","امام مالک رحمہ اللہ نے فرمایا: نہ تو مدبر غلام کو بیچنا جائز ہے اور نہ کسی کے لیے یہ جائز ہے کہ وہ اسے خریدے، الا یہ کہ مدبر خود اپنے آپ کو اپنے آقا سے خریدے تو یہ اس کے لیے جائز ہے، یا کوئی شخص مدبر کے آقا کو (کچھ) مال دے (تاکہ اس کے عوض) مدبر کا آقا جس نے اسے مدبر بنایا تھا، اسے آزاد کر دے، تو یہ بھی اس کے لیے جائز ہے۔","قَالَ مَالِكٌ : وَوَلَاؤُهُ لِسَيِّدِهِ الَّذِي دَبَّرَهُ.","امام مالک رحمہ اللہ نے فرمایا کہ (اس صورت میں) ولاء اسی آقا کی ہوگی جس نے اسے مدبر بنایا تھا۔","۔۔۔۔۔ مال دینے والے نے چونکہ نہ اسے خریدا ہے اور نہ آزاد کیا ہے، اس لیے اسے کچھ نہ ملے گا، البتہ غلام کا فائدہ ہو جائے گا کہ اسے آزادی مل گئی اور آقا کو اس کا بدل بھی اور ولاء بھی مل گئے۔","قَالَ مَالِكٌ : لَا يَجُوزُ بَيْعُ خِدْمَةِ الْمُدَبَّرِ ، لِأَنَّهُ غَرَرٌ إِذْ لَا يُدْرَى كَمْ يَعِيشُ سَيِّدُهُ ، فَذَلِكَ غَرَرٌ لَا يَصْلُحُ.","امام مالک رحمہ اللہ نے فرمایا کہ مدبر غلام کی خدمت کی خرید و فروخت ناجائز ہے، کیونکہ یہ دھوکا ہے، اسے کچھ علم نہیں کہ اس کا آقا کتنا عرصہ زندہ رہے گا، لہٰذا یہ دھوکا ہے جو کہ درست نہیں ہے۔","۔۔۔۔۔ مثلاً آقا سے کوئی شخص ایک ماہ کے لیے مدبر کی خدمت خرید لے لیکن اگلے ہی دن آقا فوت ہو جائے اور مدبر غلام آزاد ہو جائے تو خریدنے والے کا مال ضائع ہو جائے گا، کیونکہ اس نے تو مدبر غلام کی خدمت خریدی تھی اور وہ تو اب آزاد ہو چکا ہے۔ بہر حال خدمت مدبر ایک مجہول چیز ہے جس کی بیع حرام ہے۔ احناف اسے درست سمجھتے ہیں اور اس کی دلیل میں سنن دار قطنی کی ایک روایت پیش کرتے ہیں جو مرفوعاً اور مرسلاً دونوں طرح ہی ضعیف ہے۔","وَقَالَ مَالِكٌ فِي الْعَبْدِ يَكُونُ بَيْنَ الرَّجُلَيْنِ ، فَيُدَبِّرُ أَحَدُهُمَا حِصَّتَهُ : إِنَّهُمَا يَتَقَاوَمَانِهِ ، فَإِنِ اشْتَرَاهُ الَّذِي دَبَّرَهُ كَانَ مُدَبَّراً كُلُّهُ ، وَإِنْ لَمْ يَشْتَرِهِ ، انْتَقَضَ تَدْبِيرُهُ إِلَّا أَنْ يَشَاءَ الَّذِي بَقِيَ لَهُ فِيهِ الرِّقُّ أَنْ يُعْطِيَهُ شَرِيكَهُ الَّذِي دَبَّرَهُ بِقِيمَتِهِ ، فَإِنْ أَعْطَاهُ إِيَّاهُ بِقِيمَتِهِ ، لَزِمَهُ ذَلِكَ وَكَانَ مُدَبَّراً كُلُّهُ.","امام مالک رحمہ اللہ نے اس غلام کے متعلق فرمایا جو دو آدمیوں کے درمیان (مشترکہ) ہو، چنانچہ ان میں سے ایک اپنے حصے کو مدبر بنا دیتا ہے، تو بلاشبہ دونوں (مالک) اس غلام کی قیمت لگائیں گے، پھر جس نے اسے مدبر بنایا تھا وہ اگر اس (غلام کے دوسرے حصے) کو خرید لے تو وہ سارا ہی مدبر غلام بن جائے گا اور اگر وہ اسے نہ خریدے تو اس کا مدبر بنانے کا عمل باطل ہو جائے گا، الا یہ کہ جس کی اس مدبر میں غلامی (پر ملکیت) باقی تھی، وہ یہ چاہے کہ غلام کو مدبر بنانے والا اس کا شریک (آقا) اسے اس کی قیمت دے دے، پھر اگر وہ اسے اس کی قیمت دے دے تو یہ (مدبر بنانا) اس کو لازم ہو جائے گا اور وہ غلام سارے کا سارا ہی مدبر بن جائے گا۔","وَقَالَ مَالِكٌ فِي رَجُلٍ نَصْرَانِيٍّ دَبَّرَ عَبْداً لَهُ نَصْرَانِيًّا، فَأَسْلَمَ الْعَبْدُ. قَالَ مَالِكٌ : يُحَالُ","امام مالک رحمہ اللہ نے ایک عیسائی آدمی کے متعلق فرمایا جس نے اپنے عیسائی غلام کو مدبر بنا دیا، پھر غلام (اپنے آقا سے بَيْنَهُ وَبَيْنَ الْعَبْدِ، وَيُخَارَجُ عَلَى سَيِّدِهِ النَّصْرَانِيِّ، وَلَا يُبَاعُ عَلَيْهِ حَتَّى يَتَبَيَّنَ أَمْرُهُ، فَإِنْ هَلَكَ النَّصْرَانِيُّ وَعَلَيْهِ دَيْنٌ، قُضِيَ دَيْنُهُ مِنْ ثَمَنِ الْمُدَبَّرِ، إِلَّا أَنْ يَكُونَ فِي مَالِهِ مَا يَحْمِلُ الدَّيْنَ، فَيَعْتِقُ الْمُدَبَّرُ پہلے) مسلمان ہو گیا، تو امام مالک رحمہ اللہ نے فرمایا: اس (عیسائی آقا) کے درمیان اور (نومسلم) غلام کے درمیان رکاوٹ حائل کر دی جائے گی۔ (مسلمان کے شایان شان نہیں کہ اسے کافر کی غلامی میں رہنے دیا جائے) اور اس سے عیسائی آقا کے لیے آمدنی طلب کی جائے گی (کہ کمائی کر اور کافر آقا کو دے کر اپنی جان چھڑا کر آزاد ہو جا) اور غلام کو اس آقا کی طرف سے بیچا نہ جائے گا، یہاں تک کہ اس (آقا) کا معاملہ واضح ہو جائے۔ (چنانچہ اگر آقا بھی مسلمان ہو جائے تو غلام اس کی ملکیت میں لوٹ آئے گا اور اگر آقا مر جائے تو وہ آزاد ہو جائے گا)، پھر اگر وہ عیسائی آقا اس حال میں فوت ہو کہ اس پر قرض ہو تو اس کا قرض مدبر غلام کی قیمت سے ادا کیا جائے گا، الا یہ کہ میت کے مال میں اتنی گنجائش ہو جو قرضے کو برداشت کر سکے تو (اس صورت میں) مدبر غلام آزاد ہو جائے گا۔"],"438":["§خلاصۃ الباب","اس باب میں ایک مقطوع روایت یعنی اثر تابعی ہے جو سنداً ضعیف ہے، نیز امام مالک رحمہ اللہ کے چار فتاویٰ مذکور ہیں۔"],"439":["§خلاصۃ الباب","اس باب میں صرف ایک فتویٰ امام مالک رحمہ اللہ مذکور ہے۔","قَالَ مَالِكٌ فِي أُمِّ الْوَلَدِ تَجْرَحُ: إِنَّ عَقْلَ ذَلِكَ الْجَرْحِ ضَامِنٌ عَلَى سَيِّدِهَا فِي مَالِهِ، إِلَّا أَنْ يَكُونَ عَقْلُ ذَلِكَ الْجَرْحِ أَكْثَرَ مِنْ قِيمَةِ أُمِّ","امام مالک رحمہ اللہ نے ام ولد لونڈی کے متعلق فرمایا جو کسی کو زخم لگا دے، بلاشبہ اس زخم کی دیت کی ضمانت اس کے آقا پر ہے جو وہ اپنے مال سے ادا کرے گا، الا یہ کہ اس زخم کی الْوَلَدِ، فَلَيْسَ عَلَى سَيِّدِهَا أَنْ يُخْرِجَ أَكْثَرَ مِنْ قِيمَتِهَا، وَذَلِكَ أَنَّ رَبَّ الْعَبْدِ أَوِ الْوَلِيدَةِ إِذَا أَسْلَمَ غُلَامَهُ أَوْ وَلِيدَتَهُ بِجُرْحٍ أَصَابَهُ وَاحِدٌ مِنْهُمَا، فَلَيْسَ عَلَيْهِ أَكْثَرُ مِنْ ذَلِكَ، وَإِنْ كَثُرَ الْعَقْلُ، فَإِذَا لَمْ يَسْتَطِعْ سَيِّدُ أُمِّ الْوَلَدِ أَنْ يُسَلِّمَهَا، لِمَا مَضَى فِي ذَلِكَ مِنَ السُّنَّةِ، فَإِنَّهُ إِذَا أَخْرَجَ قِيمَتَهَا، فَكَأَنَّهُ أَسْلَمَهَا، فَلَيْسَ عَلَيْهِ أَكْثَرُ مِنْ ذَلِكَ وَهَذَا أَحْسَنُ مَا سَمِعْتُ، وَلَيْسَ عَلَيْهِ أَنْ يَحْمِلَ مِنْ جِنَايَتِهَا أَكْثَرَ مِنْ قِيمَتِهَا.","دیت اس ام ولد کی قیمت سے زیادہ ہو، چنانچہ اس کے آقا پر یہ لازم نہیں کہ اس کی قیمت سے زیادہ ادا کرے (بلکہ اس صورت میں ام ولد کی قیمت ہی پر اکتفا کیا جائے گا) اور یہ اس وجہ سے ہے کہ بے شک غلام یا لونڈی کا مالک جب اپنی لونڈی یا غلام کو (زخمی شخص کے) سپرد کر دیتا ہے، اس جرم کے بدلے جس کا ارتکاب ان دونوں میں سے کسی نے کیا تھا تو آقا پر اس (کی قیمت) سے زیادہ کچھ بھی لازم نہیں آتا، اگرچہ دیت کتنی ہی زیادہ ہو (کیونکہ یہ جرم غلام یا لونڈی نے کیا ہوتا ہے، نہ کہ آقا نے، اس لیے آقا پر زیادہ چھٹی نہیں پڑتی، اب زخمی آدمی کی مرضی ہے کہ چاہے تو غلام لونڈی کو رکھ لے اور چاہے تو ان کی قیمت وصول کر لے، لیکن ام ولد لونڈی میں یہ اختیار بھی نہیں رہتا، بلکہ اس کی صرف قیمت ہی ادا کرنا ہوتی ہے، خود ام ولد لونڈی کو زخمی شخص کے سپرد نہیں کیا جاتا، چنانچہ امام مالک رحمہ اللہ فرماتے ہیں:) پھر جب ام ولد لونڈی کا آقا یہ طاقت نہیں رکھتا کہ اسے سپرد کرے، کیونکہ اس بارے میں سنت یہی جاری ہے (اور مسلمانوں کا طریقہ یہی چلا آ رہا ہے کہ ام ولد کو نہ بیچا جاتا ہے اور نہ ہبہ وصدقہ کیا جا سکتا ہے) تو بلاشبہ جب آقا اس کی قیمت نکال کر زخمی کو ادا کر) دے گا تو (یہ ایسے ہی ہے کہ) گویا اس نے لونڈی ہی اس کے سپرد کر دی ہے، بہر حال اس (آقا) پر اس سے زیادہ کچھ لازم نہیں ہے اور یہی وہ سب سے بہترین فیصلہ ہے جو میں نے سنا ہے اور آقا پر یہ واجب نہیں ہے کہ اس (ام ولد) کے جرم کی وجہ سے اس کی قیمت سے زیادہ کا بوجھ اٹھائے۔"],"440":["§کتاب کا تعارف","اس کتاب میں ۴۶ ابواب اور ۹۶ روایات ہیں، جن میں سے ۴۱ مرفوع احادیث نبویہ، ۲۹ موقوف (آثار صحابہ) اور ۲۶ مقطوع (آثار تابعین) ہیں، پھر ان تمام میں سے ۷۲ سنداً صحیح، ۳ حسن اور ۲۱ ضعیف ہیں، چنانچہ ۴۱ مرفوع روایات میں سے ۳۷ صحیح، ۲ حسن اور ۲ ضعیف ہیں۔ ۲۹ موقوف روایات میں سے ۱۴ صحیح، ایک حسن اور ۱۴ ضعیف ہیں اور ۲۶ مقطوع روایات میں سے ۲۱ صحیح اور ۵ ضعیف ہیں، نیز امام مالک رحمہ اللہ کے ۱۵۱ فتاویٰ جات بھی اس کتاب میں مذکور ہیں۔","چونکہ بیع یعنی خرید وفروخت کی مختلف اقسام ہیں اسی لیے یہ لفظ جمع کے صیغے سے ’’بیوع‘‘ ذکر کیا گیا ہے۔ عموماً بیع کے معنی بیچنے اور ’’شراء‘‘ کے معنی خریدنے کے ہوتے ہیں، لیکن دراصل دونوں کا استعمال بیچنے پر بھی اور خریدنے پر بھی ہوتا ہے، اس لیے ان دونوں لفظوں کو ’’اضداد‘‘ میں شمار کیا جاتا ہے، یعنی وہ الفاظ جن کا استعمال باہم متضاد معانی کے لیے ہوتا ہے۔ عموماً بیچنے والے کو ’’بائع‘‘ اور خریدنے والے کو ’’مشتری‘‘ کہتے ہیں۔ بیع کی لغوی تعریف یوں کی جاتی ہے: «الْمُبَادَلَةُ بِمَالٍ بِغَرَضِ الْمِلْكِ» ’’ملکیت بنانے کی غرض سے مال کا مال سے تبادلہ کرنا۔‘‘ اور شرعی اصطلاح میں ’’باہمی رضا مندی کی شرط‘‘ اس مذکورہ تعریف میں بڑھا دی جاتی ہے، جیسا کہ ایک حدیث مبارکہ میں بھی ہے: «إِنَّمَا الْبَيْعُ عَنْ تَرَاضٍ» ’’یقیناً خرید وفروخت تو صرف اور صرف باہمی رضا مندی ہی سے (جائز) ہے۔‘‘ (ابن ماجہ: ۲۱۸۵، اس کی سند صحیح ہے۔ ارواء الغلیل: ۱۲۸۳) بیع کے چار ارکان ہوتے ہیں: بائع (بیچنے والا)، مشتری (خریدار) بیع (وہ چیز جس کی خرید وفروخت ہو) اور ثمن (قیمت)۔ خرید وفروخت کی تمام اقسام چار قسموں سے پھوٹتی ہیں جو کہ حسب ذیل ہیں: (۱) سامان کے بدلے سامان کی بیع۔ اسے مقابضہ بھی کہتے ہیں۔ (۲) نقدی کے بدلے سامان کی بیع۔ اسے بیع ہی کہتے ہیں۔ (۳) نقدی کے بدلے نقدی کی بیع، اسے ’’صرف‘‘ کہتے ہیں، یعنی کرنسی تبدیل کرانا، چینج لینا۔ (۴) کسی بھی مال کے بدلے منفعت کی بیع یعنی مال کے بدلے کوئی نفع اٹھانا۔ اسے ’’اجارہ‘‘ (کرایہ پر دینا، مزدور رکھنا) بھی کہتے ہیں۔۔۔۔۔ بیع جائز ہونے کے لیے مندرجہ ذیل شروط ہیں: (۱) عقد (معاملہ) کرنے والا عقل اور تمیز رکھتا ہو (۲) بیع (بیچی جانے والی چیز) معلوم اور مملوک ہو، یعنی عقد بیع کرنے والے کی ملکیت میں ہو اور مجہول یا معدوم نہ ہو۔ (۳) ثمن یا قیمت سپرد کی جانے والی چیز ہو۔ (۴) فریقین راضی ہوں۔ (۵) عقد ماضی پر دلالت کرنے والے لفظ سے ہو۔","§خلاصۃ الباب","اس باب میں ایک حدیث نبوی ہے جو سنداً حسن ہے، نیز امام مالک رحمہ اللہ کے چھ فتاویٰ مذکور ہیں۔","عربان کو ’’عربون‘‘ بھی کہتے ہیں، اردو میں بیعانہ کو ’’بیانہ‘‘ بھی لکھ دیتے ہیں جو صحیح نہیں ہے، اسے ’’سائی دینا‘‘ بھی کہتے ہیں۔ بیعانہ سے مراد وہ تھوڑی سی رقم ہے جو سودا پکا کرنے کے لیے خریدار کی طرف سے خریداری سے پہلے ادا کر دی جاتی ہے اور اس میں یہ شرط ہوتی ہے کہ اگر خریدار نے مقررہ وقت پر چیز خرید لی تو یہ بیعانہ بھی کل قیمت میں شمار ہوگا اور اگر اس نے سودا چھوڑ دیا تو یہ بیعانہ بائع کے قبضے میں چلا جائے گا۔۔۔۔ جمہور یعنی امام ابوحنیفہ، امام مالک اور امام شافعی رحمہم اللہ کے نزدیک یہ حرام ہے کیونکہ یہ رقم بغیر کسی عوض کے بائع کو ملتی ہے، اور اگر کوئی شخص ایسا کر لے تو بائع پر لازم ہے کہ بیعانہ واپس کرے۔ لیکن امام احمد رحمہ اللہ اور بہت سے اہل حدیث اس کے جواز کے قائل ہیں اور سیدنا عمر اور سیدنا ابن عمر رضی اللہ عنہما سے بھی یہی مروی ہے، دراصل اس بارے میں دونوں قسم کی احادیث مروی ہیں اور سنداً سب کی سب ضعیف ہیں، جس روایت میں اسے حلال کہا گیا ہے وہ مرسل بھی ہے اور اس میں ابراہیم بن ابی یحییٰ ضعیف راوی بھی ہے۔ (ابن ابی شیبہ: ۲۳۱۹۵، التلخیص الحبیر: ۳۹/۳) اور جس روایت میں ممانعت ہے جو موطا میں بھی آ رہی ہے اس میں ایک راوی مجہول ہے جس کا نام تک معلوم نہیں، اگرچہ چند علماء نے اسے حسن یا صحیح بھی کہا ہے لیکن محدثین کے اصول کے مطابق مجہول توثیق ناقابل قبول ہے، اسی لیے اکثر علماء اور علامہ البانی رحمہ اللہ نے بھی اسے ضعیف قرار دیا ہے۔ (ضعیف ابن ماجہ: ۴۷۵)"],"441":["§خلاصۃ الباب","اس باب میں صرف ایک موقوف روایت (اثر صحابی) ہے جو سنداً صحیح ثابت ہے، نیز امام مالک رحمہ اللہ کا ایک فتویٰ بھی مذکور ہے۔","پیچھے کتاب العتق میں یہی مسئلہ بیان کیا گیا تھا لیکن وہ غلام کی آزادی کے حوالے سے تھا کہ غلام جب آزاد ہو تو اپنے مال کو بھی ساتھ لے جائے گا اور یہاں غلام کی خریداری کی بات ہو رہی ہے، نہ کہ آزادی کی۔"],"442":["§خلاصۃ الباب","اس باب میں ایک مقطوع روایت (اثر تابعی) ہے جو سنداً صحیح ہے، نیز امام مالک رحمہ اللہ کے دو فتاویٰ بھی مذکور ہیں۔","عنوان سے مراد یہ ہے کہ غلاموں اور لونڈیوں کو بیچنے کے بعد کتنے عرصے تک بیچنے والا ذمہ دار، جواب دہ اور قابل مواخذہ رہتا ہے، اگر ان میں کوئی عیب ظاہر ہو جائے تو وہ بیچنے والے کے حق میں کب تک شمار کیا جائے گا اور کس صورت میں بائع اپنے بیچے ہوئے غلاموں اور لونڈیوں سے بری الذمہ ہوتا ہے اور خریدار کے لیے کب تک غلاموں کی بیع واپس کرنے کا اختیار رہتا ہے۔"],"443":["§خلاصۃ الباب","اس باب میں ایک موقوف روایت (اثر صحابی رضی اللہ عنہ) ہے جو سنداً ضعیف ہے، نیز امام مالک رحمہ اللہ کے سات فتاویٰ جات مذکور ہیں۔"],"444":["§خلاصۃ الباب","اس باب میں دو موقوف روایات (آثار صحابہ) ہیں جن میں سے ایک صحیح اور ایک ضعیف ہے، نیز امام مالک رحمہ اللہ کا ایک فتویٰ بھی مذکور ہے۔"],"445":["§خلاصۃ الباب","اس باب میں دو موقوف روایات ہیں، جن میں سے ایک صحیح اور ایک ضعیف سند والی ہے۔"],"446":["§خلاصۃ الباب","اس باب میں صرف ایک مرفوع روایت یعنی حدیث نبوی صلی اللہ علیہ وسلم ہے جو کہ بخاری ومسلم میں بھی موجود ہے۔","مال سے مراد درخت یا بیلیں ہیں، دراصل کبھی تو درختوں کا صرف پھل بیچا جاتا ہے اور کبھی انھیں مکمل جڑوں سمیت بیچ دیتے ہیں، یہاں دوسری صورت کا بیان ہے۔"],"447":["§خلاصۃ الباب","اس باب میں چار روایات ہیں، تین مرفوع (احادیث نبویہ) ہیں اور ایک موقوف (اثر صحابی) ہے اور سب کی سب سند صحیح ہیں، نیز امام مالک رحمہ اللہ کے دو فتاویٰ بھی مذکور ہیں۔","’’صلاح‘‘ سے مراد ہر پھل کی وہ صلاحیت ہے کہ جس کی موجودگی میں اس کا استعمال درست ہو جاتا ہے، عموماً تو اس سے پکنا اور پختگی ظاہر ہونا ہی مراد لیتے ہیں یعنی ہر پھل پکنے کے وقت جو رنگ اختیار کرتا ہے جب وہ ظاہر ہونا شروع ہو جائے تو اس پھل کی خرید و فروخت جائز ہو جاتی ہے، لیکن بہت سے پھلوں کو رنگ ظاہر ہونے سے پہلے ہی مختلف مقاصد کی خاطر استعمال کیا جاتا ہے اور متعدد پھلوں کا حال یہ ہے کہ اپنی نزاکت کی وجہ سے وہ رنگ شروع ہوتے ہی فوراً پک جاتے ہیں اور پھر جلد ہی خراب ہو جاتے ہیں، اس لیے ایسے پھلوں کا استعمال اور انتقال کے قابل ہو جانا بھی ’’بدو صلاح‘‘ یعنی صلاحیت کے ظاہر ہونے میں شامل ہے، چنانچہ اچار اور مربہ بنانے کے لیے بعض پھلوں کو رنگ پکڑنے سے پہلے ہی اتارنا پڑتا ہے جیسا کہ آم ہے اور بعض پھلوں کو ان کی جسامت پوری ہونے کے بعد اور رنگ پکڑنے سے پہلے ہی منتقل کیا جا سکتا ہے، مثلاً کیلا اور آم وغیرہ، لہذا ان پھلوں کا قابل استعمال و انتقال ہو جانا بھی الفاظ نبویہ کی جامعیت میں شامل ہے کہ ان کی صلاحیت ظاہر ہو جانا کافی ہے۔ واللہ اعلم۔ نیز فصلوں کے متعلق بھی یہی حکم ہے کہ دانہ سخت ہونے سے پہلے انھیں نہ بیچا جائے۔ (ابوداود: ۳۳۷۱، ترمذی: ۱۲۲۸، ابن ماجہ: ۲۲۱۷ اس کی سند صحیح ہے) لیکن اگر اس فصل کو چارے کے طور پر بیچنا ہو تو اس کا حکم تبدیل ہو جائے گا اور وہ جائز ہے۔"],"448":["§خلاصۃ الباب","اس باب میں دو مرفوع روایات (احادیث نبویہ) ہیں جو بخاری ومسلم میں موجود ہیں۔ نیز امام مالک رحمہ اللہ کا ایک فتویٰ بھی مذکور ہے۔","عَرِیہ کی جمع ’’عَرَایَا‘‘ ہے جیسا کہ عَطِیَّہ کی جمع عَطَایَا۔ عَرِیہ سے مراد وہ درخت ہے جو کسی باغ وغیرہ کا مالک کسی مسکین کو عاریتاً دے دیتا ہے کہ اس فلاں درخت سے جو بھی پھل حاصل ہو وہ اس مسکین کا ہوگا، پھر مسکین کے اپنی ضرورت کی بنا پر بار بار آنے کی وجہ سے باغ یا گھر والوں کو تنگی کا سامنا کرنا پڑتا ہے، اس لیے اس درخت پر لگے ہوئے تازہ پھل کا گھر میں موجود خشک پھل کے ساتھ تبادلہ کرنا بعض شروط کے ساتھ جائز رکھا گیا ہے، اس تبادلے کو ’’بیع العریّہ‘‘ کہتے ہیں، یہ صرف مسکینوں پر احسان کرنے کے لیے مشروع ہوا ہے، ورنہ درحقیقت اسے ’’بیع مزابنہ‘‘ کہتے ہیں جو کہ حرام ہے اور اس کا تفصیلی بیان آگے تیرھویں باب میں آ رہا ہے۔"],"449":["§خلاصۃ الباب","اس باب میں دو روایات ہیں، ایک مرفوع ہے جو بخاری ومسلم میں بھی موجود ہے اور ایک مقطوع یعنی اثر تابعی رحمہ اللہ ہے جو سنداً ضعیف ہے، نیز امام مالک رحمہ اللہ کا ایک فتویٰ بھی مذکور ہے۔"],"450":["§خلاصۃ الباب","اس باب میں تین مقطوع روایات (آثار تابعین) ہیں جن میں سے ایک ضعیف اور دو صحیح ہیں، نیز امام صاحب کے دو فتاویٰ بھی مذکور ہیں۔","سیدنا جابر رضی اللہ عنہ کی روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے (خرید و فروخت میں) استثناء کرنے سے منع فرمایا ہے۔ (مسلم: ۱۵۳۶) البتہ دوسری حدیث میں یہ بھی موجود ہے: ’’الا یہ کہ معلوم کرا دیا جائے۔‘‘ (ابوداود: ۳۴۰۵، ترمذی: ۱۲۹۰، نسائی: ۴۶۳۷، اس کی سند صحیح ہے) الغرض اگر مجہول استثناء ہو تو حرام ہے اور اگر معلوم و متعین استثناء ہو تو جائز ہے۔"],"451":["§خلاصۃ الباب","اس باب میں تین مرفوع روایات یعنی احادیث نبویہ ہیں اور سب کی سب سنداً صحیح ہیں۔"],"452":["§خلاصۃ الباب","اس باب میں تین مرفوع روایات احادیث نبویہ ہیں جو بخاری و مسلم کی روایات میں سے ہیں، نیز امام مالک رحمہ اللہ کے دو فتاویٰ بھی مذکور ہیں۔"],"453":["§خلاصۃ الباب","اس باب میں کوئی روایت نہیں ہے، البتہ امام مالک رحمہ اللہ کے دس فتاویٰ جات مذکور ہیں۔","قَالَ مَالِكٌ: مَنِ اشْتَرَى ثَمَراً مِنْ نَخْلِ مُسَمَّاةٍ، أَوْ حَائِطٍ مُسَمًّى، أَوْ لَبَناً مِنْ غَنَمٍ مُسَمَّاةٍ، إِنَّهُ لَا بَأْسَ بِذَلِكَ إِذَا كَانَ يُؤْخَذُ عَاجِلاً، يَشْرَعُ الْمُشْتَرِي فِي أَخْذِهِ عِنْدَ دَفْعِهِ الثَّمَنَ، وَإِنَّمَا مَثَلُ ذَلِكَ، بِمَنْزِلَةِ رَاوِيَةِ زَيْتٍ، يَبْتَاعُ مِنْهَا رَجُلٌ بِدِينَارٍ أَوْ دِينَارَيْنِ، وَيُعْطِيهِ ذَهَبَهُ، وَيَشْتَرِطُ عَلَيْهِ أَنْ يَكِيلَ لَهُ مِنْهَا، فَهَذَا لَا بَأْسَ بِهِ، فَإِنِ انْشَقَّتِ الرَّاوِيَةُ، فَذَهَبَ زَيْتُهَا، فَلَيْسَ لِلْمُبْتَاعِ إِلَّا ذَهَبُهُ، وَلَا يَكُونُ بَيْنَهُمَا بَيْعٌ.","امام مالک رحمہ اللہ نے فرمایا: جس شخص نے کسی متعین کھجور یا مخصوص باغ سے پھل خریدا، یا متعین بکریوں کا دودھ خریدا تو بلاشبہ اس میں کوئی حرج نہیں ہے، (لیکن شرط یہ ہے کہ) جب ان کو نقد خریدا جائے (اور) خریدار قیمت ادا کرتے وقت ہی اسے وصول کرنے میں شروع ہو جائے اور بلاشبہ ان (سب) کی مثال زیتون کے تیل والی اس مشک جیسی ہے جس سے کوئی شخص ایک دینار یا دو دینار کے بدلے تیل خریدتا ہے اور اس کے مالک کو اپنا سونا (یعنی دینار) دے دیتا ہے اور اس پر یہ شرط لگا لیتا ہے کہ وہ خریدار کو اسی (مخصوص مشک) سے ماپ کر دے گا، تو اس میں کوئی حرج نہیں ہے، پھر اگر وہ مشک (ادائیگی سے قبل ہی) پھٹ جائے اور زیتون کا تیل بہہ جائے تو خریدار کے لیے اس کے سونے (یعنی ادا کردہ رقم) کے سوا کچھ نہیں ہوگا اور نہ ہی ان دونوں کے درمیان کوئی خرید وفروخت ہوگی۔","عموماً درختوں کا پھل الگ الگ حیثیت کا حامل ہوتا ہے، بعض کا میٹھا، بعض کا ترش، بعض کا اعلیٰ اور بعض کا ادنیٰ، اسی طرح بعض جانوروں کا دودھ بعض دوسرے جانوروں کی نسبت بہتر ہوتا ہے، جس طرح کہ دکانوں میں مختلف قسم کی ورائٹی کا مال پڑا ہوتا ہے، اگر کوئی شخص ان مذکور چیزوں کے مالک سے صرف اتنا طے کر لے کہ میں فلاں درخت کا پھل یا فلاں جانور کا دودھ لوں گا، اور کسی کا نہیں لوں گا، تو اتنی سی بات کرنے میں کوئی حرج نہیں ہے، البتہ اس میں مندرجہ ذیل شرطیں ملحوظ رکھنا لازم ہے: (۱) درخت یا جانور متعین ہو (۲) ادائیگی سے قبل ہونے والے نقصان کا ذمہ دار مالک ہو، نہ کہ خریدار۔ (۳) سودا طے کر لینے کے بعد قیمت ادا کرتے ہی نقد ونقد لین دین ہو جائے اور بلا ضرورت تاخیر نہ کی جائے، ہاں اگر درخت کے پھل میں کچھ کچا پن باقی ہو تو تاخیر ہوسکتی ہے، لیکن اس تاخیر کے دوران میں بھی نقصان ہو جانے کی صورت میں مالک (بیچنے والا) ذمہ دار ہوگا۔۔۔۔۔ امام مالک رحمہ اللہ نے جانوروں کے تھنوں میں موجود دودھ کی بیع کے لیے مندرجہ بالا صورت میں اجازت دی ہے لیکن باقی ائمہ ثلاثہ اس کو بھی درست نہیں سمجھتے، کیونکہ بعض روایات میں صراحتاً اس کی ممانعت مروی ہے۔ (ابن ماجہ: ۲۱۹۶، مسند احمد: ۴۲/۳، دارقطنی: ۱۴/۳ وغیرہ) اگرچہ یہ روایات ضعیف ہیں، لیکن چونکہ مذکورہ بیع میں دھوکے کا بھی اندیشہ ہے اور دودھ کی مقدار بھی مجہول ہے، اس لیے یہ بیع الغرر میں شامل ہے اور ناجائز ہے، ہاں اگر صرف یہ تعین ہو کہ فلاں جانور ہی کا دودھ لیں گے اور بیع کا تعلق حاصل شدہ دودھ اور اس کی مقدار کے مطابق ہو تو پھر کوئی حرج نہیں۔۔۔۔۔ بہر حال درخت وغیرہ کی تعیین میں کوئی حرج نہیں، بشرطیکہ اس سے خریدے جانے والے پھل کی مقدار بھی متعین ہو۔","قَالَ مَالِكٌ: وَأَمَّا كُلُّ شَيْءٍ كَانَ حَاضِراً يُشْتَرَى عَلَى وَجْهِهِ، مِثْلُ اللَّبَنِ إِذَا حُلِبَ، وَالرُّطَبِ يُسْتَجْنَى، فَيَأْخُذُ الْمُبْتَاعُ يَوْماً بِيَوْمٍ، فَلَا بَأْسَ بِهِ، فَإِنْ فَنِيَ قَبْلَ أَنْ يَسْتَوْفِيَ الْمُشْتَرِي مَا اشْتَرَى، رَدَّ عَلَيْهِ الْبَائِعُ مِنْ ذَهَبِهِ، بِحِسَابِ مَا بَقِيَ لَهُ، أَوْ يَأْخُذُ مِنْهُ الْمُشْتَرِي سِلْعَةً بِمَا بَقِيَ لَهُ، يَتَرَاضَيَانِ عَلَيْهَا، وَلَا يُفَارِقُهُ حَتَّى يَأْخُذَهَا، فَإِنْ فَارَقَهُ فَإِنَّ ذَلِكَ مَكْرُوهٌ، لِأَنَّهُ يَدْخُلُهُ الدَّيْنُ","امام مالک رحمہ اللہ نے فرمایا: (اسی طرح) رہی ہر وہ چیز جو حاضر ہو جسے اس کی موجودہ حالت پر ہی خریدا جائے مثلاً دودھ کو جب کہ وہ دوھ لیا جائے اور کھجوروں کو جب انھیں اتار لیا جائے، چنانچہ خریدار روزانہ کے حساب سے (حاصل شدہ دودھ یا کھجور) وصول کرتا رہے تو اس میں کوئی حرج نہیں ہے) کہ متعینہ مقدار کی قیمت پیشگی ادا کر دے اور چیز کی وصولی روزانہ کے حساب سے تھوڑی تھوڑی کرتا رہے، اتنی مقدار میں کہ جتنی وہ چیز تیار ہو کر ملتی رہے تو کوئی حرج نہیں، کیونکہ یہ ایک طرف نقد اور ایک طرف ادھار کی بِالدَّيْنِ، وَقَدْ نُهِيَ عَنِ الْكَالِئِ بِالْكَالِئِ، فَإِنْ وَقَعَ فِي بَيْعِهِمَا أَجَلٌ، فَإِنَّهُ مَكْرُوهٌ، وَلَا يَحِلُّ فِيهِ تَأْخِيرٌ، وَلَا نَظِرَةٌ، وَلَا يَصْلُحُ إِلَّا بِصِفَةٍ مَعْلُومَةٍ إِلَى أَجَلٍ مُسَمًّى، فَيَضْمَنُ ذَلِكَ الْبَائِعُ لِلْمُبْتَاعِ، وَلَا يُسَمَّى ذَلِكَ فِي حَائِطٍ بِعَيْنِهِ، وَلَا فِي غَنَمٍ بِأَعْيَانِهَا.","صورت ہے یعنی بائع پر ادھار ہے) پھر اگر وہ چیز اس سے پہلے ختم ہو جائے کہ خریدار اس مطلوبہ مقدار کو پورا حاصل کرتا جسے اس نے خریدا ہوا تھا (اور قیمت ادا کر رکھی تھی، مثلاً روزانہ دو کلو گرام کے حساب سے ایک من دودھ لینا تھا، لیکن یہ مطلوبہ مقدار مکمل وصول ہونے سے پہلے ہی دودھ دینا بند کر دیا، یا مر گیا یا درخت کا پھل ختم ہو گیا) تو بیچنے والا اس خریدار کو اس کا سونا اس (دودھ یا کھجور کے) حساب سے واپس کرے گا جو اس کے لیے باقی رہ گیا تھا، یا مشتری بائع سے اپنے باقی ماندہ کے عوض کوئی ایسا سامان خرید لے جس پر وہ دونوں راضی ہوں، اور وہ اس سے جدا نہ ہو یہاں تک کہ اس کے سودے کو وصول کر لے، چنانچہ اگر وہ اس سودے کو لینے سے پہلے) اس سے جدا ہو گیا تو بلاشبہ یہ مکروہ عمل ہے کیونکہ قرض کے بدلے قرض کا معاملہ اس لین دین میں داخل ہو جائے گا، (بائع کے ذمے پہلے ہی ادھار تھا، اب مشتری نے بھی ادھار کر لیا) اور یقیناً رسول اللہ صلی اللہ علیہ وسلم نے ادھار کے بدلے ادھار سے منع فرمایا ہے۔۔۔۔۔ لہذا اگر ان دونوں کی خرید وفروخت میں کچھ میعاد واقع ہوگئی تو یہ بھی مکروہ (اور ناجائز) ہے، اس بیع میں (خواہ مذکورہ قسم کی ہو یا کوئی اور) نہ تو تاخیر جائز ہے اور نہ مہلت، اور یہ (تاخیر و تاجیل والی) بیع درست نہیں ہو سکتی مگر صرف اس صورت میں کہ سامان کا وصف معلوم ہو اور ایک وقت مقررہ تک ہو اور بائع مشتری کے حق میں اس (مبیع چیز) کا ضامن ہوگا اور (مقررہ وقت تک اسے نہ دے سکا تو بعد میں بھی ادائیگی لازم رہے گی، لیکن قیمت وغیرہ میں اضافہ نہ ہوگا، تا کہ سود نہ بنے، نیز تاخیر والی صورت میں یہ تعیین کسی معین باغ یا بکریوں کے معین ریوڑ میں (مجمل طور پر) نہ کی جائے گی۔ (محض باغ یا ریوڑ کو معین کرنا کافی نہیں، بلکہ اس میں سے بھی جسے خریدنا ہے اس کی تعیین کرے)۔","وَسُئِلَ مَالِكٌ عَنِ الرَّجُلِ يَشْتَرِي مِنَ الرَّجُلِ الْحَائِطَ فِيهِ أَلْوَانٌ مِنَ النَّخْلِ، مِثْلُ الْعَجْوَةِ، وَالْكَبِيسِ، وَالْعَذْقِ، وَغَيْرِ ذَلِكَ مِنْ أَلْوَانِ التَّمْرِ، فَيَسْتَثْنِي مِنْهَا ثَمَرَ النَّخْلَةِ، أَوِ النَّخَلَاتِ يَخْتَارُهَا مِنْ نَخْلِهِ؟ فَقَالَ مَالِكٌ: ذَلِكَ لَا يَصْلُحُ، لِأَنَّهُ إِذَا صَنَعَ ذَلِكَ تَرَكَ ثَمَرَ النَّخْلَةِ مِنَ الْعَجْوَةِ، وَمَكِيلَةُ ثَمَرِهَا خَمْسَةَ","امام مالک رحمہ اللہ سے اس شخص کے متعلق سوال کیا گیا جو دوسرے شخص سے باغ (کا پھل) خریدتا ہے، جس میں مختلف قسم کے کھجوروں کے درخت ہوں، عجوہ کے بھی، کبیس کے بھی، عذق کے بھی، اور ان کے علاوہ کھجوروں کی دوسری قسموں کے درخت بھی ہوں، چنانچہ وہ باغ کا مالک اپنے کھجوروں کے درختوں میں سے ایک یا زیادہ درختوں کا استثناء کرلے جنھیں وہ خود پسند کرے گا، تو امام مالک رحمہ اللہ عَشَرَ صَاعاً، وَأَخَذَ مَكَانَهَا ثَمَرَ نَخْلَةٍ مِنَ الْكَبِيسِ، وَمَكِيلَةُ ثَمَرِهَا عَشَرَةُ أَصْوُعٍ، فَإِنْ أَخَذَ الْعَجْوَةَ الَّتِي فِيهَا خَمْسَةَ عَشَرَ صَاعاً، وَتَرَكَ الَّتِي فِيهَا عَشَرَةُ أَصْوُعٍ مِنَ الْكَبِيسِ، فَكَأَنَّهُ اشْتَرَى الْعَجْوَةَ بِالْكَبِيسِ مُتَفَاضِلاً.","نے فرمایا کہ یہ عمل درست نہیں ہے، کہ سود اور حرام ہے، اور وہ اس طرح کہ مثلاً وہ عجوہ کھجور کا ایک درخت چھوڑ سکتا ہے، جس کے پھل کا ماپ پندرہ صاع ہو، اور اس کی بجائے کبیس کھجور کا ایک درخت لے لیتا ہے جس کے پھل کا ماپ دس صاع ہو، لیکن وہ پندرہ صاع والے عجوہ کھجور کے درخت کو لے لیتا ہے اور دس صاع والے کبیس کھجور کے درخت کو ترک کر دیتا ہے تو گویا اس نے عجوہ کو کبیس کے بدلے کمی بیشی کے ساتھ خرید لیا ہے۔","دراصل امام مالک رحمہ اللہ اس قسم کے استثناء میں پیدا ہونے والی خرابیوں میں سے ایک خرابی ذکر کر رہے ہیں، ورنہ اس میں حرام ہونے کی اور بھی وجوہات ہیں، مثلاً مجہول اور نامعلوم چیز کی بیع بن جائے گی کہ مثلاً اگر وہ دس درختوں میں سے ایک کا استثناء کرتا ہے تو کون سے نو درختوں کا بھاؤ ہوا۔ یہ نامعلوم رہے گا۔ نیز اس میں غرر اور دھوکا ہے جو باہمی نزاع کا باعث بنے گا، بائع کی کوشش ہوگی کہ بہترین درخت مستثنیٰ کرے اور خریدار کی کوشش ہوگی کہ گھٹیا چیز کا استثناء کرے، بہر حال مجہول استثناء منع ہے اور متعین و معلوم استثناء جائز ہے، جیسا کہ پیچھے باب: ۱۱ کے آغاز میں تفصیل گزر چکی ہے۔","قَالَ مَالِكٌ: وَذَلِكَ مِثْلُ أَنْ يَقُولَ الرَّجُلُ لِلرَّجُلِ بَيْنَ يَدَيْهِ صُبَرٌ مِنَ التَّمْرِ، قَدْ صَبَرَ الْعَجْوَةَ فَجَعَلَهَا خَمْسَةَ عَشَرَ صَاعاً، وَجَعَلَ صُبْرَةَ الْكَبِيسِ عَشَرَةَ آصُعٍ، وَجَعَلَ صُبْرَةَ الْعَدْقِ اثْنَيْ عَشَرَ صَاعاً، فَأَعْطَى صَاحِبَ التَّمْرِ دِينَاراً عَلَى أَنَّهُ يَخْتَارُ فَيَأْخُذُ أَيَّ تِلْكَ الصُّبَرِ شَاءَ. قَالَ مَالِكٌ: فَهَذَا لَا يَصْلُحُ.","امام مالک رحمہ اللہ نے فرمایا: اور اس کی مثال کچھ یوں ہے کہ ایک آدمی دوسرے آدمی سے (بیع کرتے ہوئے کچھ) کہتا ہے، دوسرے آدمی کے سامنے خشک کھجوروں کے کئی ڈھیر ہوں، اس نے عجوہ کھجور کا ڈھیر لگایا تو اسے پندرہ صاع بنایا، کبیس کھجور کا ڈھیر دس صاع کا رکھا اور عذق کھجور کا ڈھیر بارہ صاع کا بنایا، پھر خریدار شخص کھجوروں کے مالک کو ایک دینار دے، اس شرط پر کہ وہ خود پسند کرے گا، پھر ان ڈھیروں میں سے جسے چاہے گا لے لے گا تو امام مالک رحمہ اللہ نے فرمایا کہ یہ ناجائز ہے۔","کیونکہ اس صورت میں بھی مجہول استثناء، مجہول بیع اور بیع الغرر لازم آ رہی ہیں، نیز وہ خریدار مختلف وزن والی ہم جنس چیزوں کو ہم پلہ قرار دے رہا ہے، گویا اس کی نظر میں ۱۵ صاع کھجور بارہ یا دس صاع کے عوض ہے اور یہ بعینہ سود ہے۔","قَالَ: وَسُئِلَ مَالِكٌ عَنِ الرَّجُلِ يَشْتَرِي","امام مالک رحمہ اللہ سے اس شخص کے متعلق سوال کیا گیا جو باغ الرُّطَبَ مِنْ صَاحِبِ الْحَائِطِ، فَيُسْلِفُهُ الدِّينَارَ، مَاذَا لَهُ إِذَا ذَهَبَ رُطَبُ ذَلِكَ الْحَائِطِ؟ قَالَ مَالِكٌ: يُحَاسِبُ صَاحِبَ الْحَائِطِ، ثُمَّ يَأْخُذُ مَا بَقِيَ لَهُ مِنْ دِينَارِهِ، إِنْ كَانَ أَخَذَ بِثُلُثَيْ دِينَارٍ رُطَباً، أَخَذَ ثُلُثَ الدِّينَارِ الَّذِي بَقِيَ لَهُ، وَإِنْ كَانَ أَخَذَ ثَلَاثَةَ أَرْبَاعِ دِينَارِهِ رُطَباً، أَخَذَ الرُّبْعَ الَّذِي بَقِيَ لَهُ، أَوْ يَتَرَاضَيَانِ بَيْنَهُمَا، فَيَأْخُذُ بِمَا بَقِيَ لَهُ مِنْ دِينَارِهِ عِنْدَ صَاحِبِ الْحَائِطِ مَا بَدَا لَهُ، إِنْ أَحَبَّ أَنْ يَأْخُذَ تَمْراً أَوْ سِلْعَةً، سِوَى التَّمْرِ أَخَذَهَا بِمَا فَضَلَ لَهُ، فَإِنْ أَخَذَ تَمْراً أَوْ سِلْعَةً، أُخْرَى، فَلَا يُفَارِقْهُ حَتَّى يَسْتَوْفِيَ ذَلِكَ مِنْهُ.","والے سے تر کھجوریں خریدتا ہے، پھر اسے (بیع سلف کے طور پر) پیشگی دینار دے دیتا ہے، تو جب (اس کی مطلوبہ مقدار پوری ہونے سے پہلے) ہی اس باغ کی تر کھجوریں ختم ہو جائیں، تو اس کے لیے کیا چیز ہوگی (اور وہ اب کیا کرے گا؟) امام مالک رحمہ اللہ نے فرمایا: وہ باغ والے سے حساب کرے گا، پھر اس کے دینار میں سے جس قدر حصہ باقی تھا وہ واپس وصول کر لے گا، اگر وہ دینار کے دو تہائی کے عوض تر کھجوریں لے چکا ہے تو اپنا باقی ماندہ تہائی دینار لے لے گا اور اگر دینار کے تین چوتھائی کے عوض تر کھجوریں لے چکا ہے تو اپنا باقی ماندہ ایک چوتھائی دینار واپس لے لے گا یا وہ دونوں آپس میں (ایک اور صورت پر) رضامند ہو جائیں تو (یہ بھی درست ہے، چنانچہ) اس کے دینار سے اس کے لیے جو حصہ، باغ والے کے پاس باقی ہے وہ اس کے عوض کوئی بھی چیز لے سکتا ہے جو بھی اس کے دل میں آئے، اگر چاہے تو خشک کھجوریں لے لے یا کھجوروں کے سوا کوئی اور سامان لے لے، تو وہ اسے اس (قیمت) کے عوض لے سکتا ہے جو (باغ والے کے پاس) زائد پڑی ہے (لیکن اس صورت میں یہ لازم ہے کہ) اگر وہ تر کھجوریں یا کوئی دوسرا سامان لے تو اسے بائع سے پورا پورا لے لینے تک جدا نہ ہو۔","تا کہ ادھار کے بدلے ادھار کی بیع لازم نہ آئے جیسا کہ پیچھے اسی باب کے دوسرے فتویٰ میں گزر چکا ہے۔","قَالَ مَالِكٌ: وَإِنَّمَا هَذَا بِمَنْزِلَةِ أَنْ يُكْرِيَ الرَّجُلُ الرَّجُلَ رَاحِلَتَهُ بِعَيْنِهَا، أَوْ يُوَاجِرَ غُلَامَهُ الْخَيَّاطَ، أَوِ النَّجَّارَ، أَوِ الْعُمَّالَ لِغَيْرِ ذَلِكَ مِنَ الْأَعْمَالِ، أَوْ يُكْرِيَ مَسْكَنَهُ، وَيَسْتَلِفَ إِجَارَةَ ذَلِكَ الْغُلَامِ، أَوْ كِرَاءَ ذَلِكَ الْمَسْكَنِ، أَوْ تِلْكَ الرَّاحِلَةِ، ثُمَّ يَحْدُثُ فِي ذَلِكَ حَدَثٌ بِمَوْتٍ، أَوْ غَيْرِ ذَلِكَ، فَيَرُدُّ","امام مالک رحمہ اللہ نے فرمایا: یقیناً یہ (گزشتہ مسئلہ) اس صورت کی طرح ہے کہ ایک آدمی دوسرے شخص کو کرائے پر اپنا متعین سواری کا اونٹ دیتا ہے، یا اپنے اس غلام کو اجرت (کرایہ) پر دیتا ہے جو کہ درزی ہو یا بڑھئی ہو یا ان کے علاوہ دوسرے کاموں (پیشوں) میں سے کسی کا کاریگر ہو یا اپنا گھر کرائے پر دیتا ہے، اور اس غلام کی اجرت یا اس گھر کا کرایہ یا اس اونٹ کا کرایہ پیشگی وصول کر لیتا ہے (لیکن رَبُّ الرَّاحِلَةِ، أَوِ الْعَبْدِ، أَوِ الْمَسْكَنِ إِلَى الَّذِي سَلَّفَهُ مَا بَقِيَ مِنْ كِرَاءِ الرَّاحِلَةِ، أَوْ إِجَارَةِ الْعَبْدِ، أَوْ كِرَاءِ الْمَسْكَنِ، يُحَاسِبُ صَاحِبَهُ بِمَا اسْتَوْفَى مِنْ ذَلِكَ، إِنْ كَانَ اسْتَوْفَى نِصْفَ حَقِّهِ, رَدَّ عَلَيْهِ النِّصْفَ الْبَاقِيَ الَّذِي لَهُ عِنْدَهُ، وَإِنْ كَانَ أَقَلَّ مِنْ ذَلِكَ، أَوْ أَكْثَرَ فَبِحِسَابِ ذَلِكَ، يَرُدُّ إِلَيْهِ مَا بَقِيَ لَهُ .","ان کا کام پورا ہونے سے پہلے) ان میں کوئی حادثہ پیش آجاتا ہے (مثلاً غلام یا اونٹ) کو موت کی صورت میں یا اس کے علاوہ کوئی اور حادثہ مثلاً بیماری وغیرہ کی صورت میں یا گر جانے کی صورت میں پیش آجاتا ہے) تو اونٹ یا غلام یا گھر کا مالک اس پیشگی ادائیگی کرنے والے کو باقی ماندہ اونٹ کا کرایہ یا غلام کی اجرت یا گھر کا کرایہ واپس کر دے گا، وہ اپنے (کرائے پر لینے والے) ساتھی کے ساتھ اس چیز کا حساب لگائے گا جو وہ اس سے حاصل کر چکا تھا، اگر تو وہ اپنے نصف حق (کی صورت میں مزدوری) کی وصولی کر چکا تھا تو وہ اس کا دوسرا نصف حق واپس لوٹائے گا، جو اس کا اس (مالک) کے ذمے ہے اور اگر اس سے کم یا زیادہ ہو تو اسی حساب سے وہ (رقم) واپس دے گا جو اس کے لیے باقی بچ گئی ہے۔","قَالَ مَالِكٌ : وَلَا يَصْلُحُ التَّسْلِيفُ فِي شَيْءٍ مِنْ هَذَا ، يُسَلَّفُ فِيهِ بِعَيْنِهِ ، إِلَّا أَنْ يَقْبِضَ الْمُسَلِّفُ ، مَا سَلَفَ فِيهِ عِنْدَ دَفْعِهِ الذَّهَبَ إِلَى صَاحِبِهِ ، يَقْبِضُ الْعَبْدَ ، أَوِ الرَّاحِلَةَ ، أَوِ الْمَسْكَنَ، أَوْ يَبْدَأُ فِيمَا اشْتَرَى مِنَ الرُّطَبِ ، فَيَأْخُذُ مِنْهُ عِنْدَ دَفْعِهِ الذَّهَبَ إِلَى صَاحِبِهِ، لَا يَصْلُحُ أَنْ يَكُونَ فِي شَيْءٍ مِنْ ذَلِكَ تَأْخِيرٌ ، وَلَا أَجَلٌ.","امام مالک رحمہ اللہ نے فرمایا: ان چیزوں میں سے کسی میں بھی پیشگی ادائیگی جائز نہیں ہے کہ جن میں کسی معین چیز کے بدلے پیشگی ادائیگی کی جارہی ہو، مگر (صرف اس صورت میں جائز ہے کہ) پیشگی ادائیگی کرنے والا اپنا سونا (یا کوئی دوسری نقدی) اپنے ساتھی کو دیتے وقت اس چیز کو (فوراً) قبضے میں لے لے جس میں اس نے پیشگی ادائیگی کی ہو، (مثلاً گزشتہ مسئلے کے مطابق) غلام یا اونٹ یا گھر کو (فوراً) قبضے میں لے لے یا (اگر اس نے کھجوریں خریدنا ہوں تو) جن تر کھجوروں کو خریدا ہے ان کے ساتھ آغاز کر لے، چنانچہ اپنے ساتھی (بائع) کی طرف سونا سپرد کرتے وقت کھجوروں میں سے کچھ وصول کر لے، (الغرض) ان میں سے کسی بھی چیز میں نہ کچھ تاخیر کرنا درست ہے، اور نہ کوئی مدت (مقرر کرنا جائز ہے)۔","قَالَ مَالِكٌ : وَتَفْسِيرُ مَا كُرِهَ مِنْ ذَلِكَ : أَنْ يَقُولَ الرَّجُلُ لِلرَّجُلِ أُسَلِّفُكَ فِي رَاحِلَتِكَ فُلَانَةَ ، أَرْكَبُهَا فِي الْحَجِّ . وَبَيْنَهُ وَبَيْنَ الْحَجِّ أَجَلٌ مِنَ الزَّمَانِ ، أَوْ يَقُولَ : مِثْلَ ذَلِكَ فِي","امام مالک رحمہ اللہ نے فرمایا: ان میں سے جو چیز مکروہ (اور ناجائز) ہے اس کی تفسیر یہ ہے کہ آدمی دوسرے شخص سے کہے کہ میں تیرے سواری والے جس اونٹ میں پیشگی ادائیگی کر رہا ہوں میں اس پر حج کے موقع پر سواری کروں گا۔","الْعَبْدِ ، أَوِ الْمَسْكَنِ ، فَإِنَّهُ إِذَا صَنَعَ ذَلِكَ ، كَانَ إِنَّمَا يُسَلِّفُهُ ذَهَباً ، عَلَى أَنَّهُ إِنْ وَجَدَ تِلْكَ الرَّاحِلَةَ صَحِيحَةً لِذَلِكَ الْأَجَلِ ، الَّذِي سَمَّى لَهُ ، فَهِيَ لَهُ بِذَلِكَ الْكِرَاءِ ، وَإِنْ حَدَثَ بِهَا حَدَثٌ ، مِنْ مَوْتٍ ، أَوْ غَيْرِهِ ، رَدَّ عَلَيْهِ ذَهَبَهُ، وَكَانَتْ عَلَيْهِ عَلَى وَجْهِ السَّلَفِ عِنْدَهُ.","حالانکہ اس (ادائیگی) اور حج کے درمیان ایک مدت، ایک عرصہ (کا وقفہ) ہو یا وہ اسی طرح کی بات (مذکورہ) غلام یا گھر کے متعلق کہے، تو بلاشبہ جب وہ ایسا کرے گا تو اس کی صورت اور معاملہ (یہ ہو جائے گا کہ) (گویا) وہ اسے اس شرط پر سونا (اور رقم) پیشگی دے رہا ہے کہ اگر اس نے اس مدت تک کہ جس کا نام لیا ہے۔ (اور تعین کی ہے اور اس کی آمد پر) اس اونٹ کو صحیح (تندرست اور قابل سواری) پا لیا تو وہ اس کرائے کے عوض اس خریدار کا ہوگا اور اگر اس میں موت وغیرہ کا کوئی حادثہ پیش آگیا تو بائع اسے اس کا (پورا) سونا لوٹا دے گا اور وہ اونٹ اس (کرایہ دینے والے یعنی بائع مکری) کے پاس اس خریدار کے لیے ادھار کے طور پر پڑا رہے گا۔","......: اور یہ صورت غرر اور دھوکے والی ہے، اس میں ایک جھگڑا تو یہ کھڑا ہو سکتا ہے کہ مکری (کرائے پر دینے والا) مستکری (کرائے پر لینے والے) سے کہنے لگے کہ میرا اونٹ تیری وجہ سے کہیں اور استعمال نہیں ہو سکا اور میں کمائی نہ کرا سکا، لہذا مجھے کچھ عوضانہ دو، اور دوسری خرابی یہ ہے کہ جس چیز کا کرایہ دے رہا ہے وہ مجہول چیز بن گئی ہے، اس لیے کہ وہ اس معاملے کو اس کے زندہ رہنے کی شرط پر طے کر رہا ہے اور اس وقت اس کا زندہ رہنا کسی کو بھی معلوم نہیں۔","قَالَ مَالِكٌ : وَإِنَّمَا فَرَقَ بَيْنَ ذَلِكَ الْقَبْضُ ، مَنْ قَبَضَ مَا اسْتَأْجَرَ ، أَوِ اسْتَكْرَى ، فَقَدْ خَرَجَ مِنَ الْغَرَرِ وَالسَّلَفِ ، الَّذِي يُكْرَهُ، وَأَخَذَ أَمْراً مَعْلُوماً ، وَإِنَّمَا مَثَلُ ذَلِكَ أَنْ يَشْتَرِيَ الرَّجُلُ الْعَبْدَ أَوِ الْوَلِيدَةَ، فَيَقْبِضَهُمَا وَيَنْقُدَ أَثْمَانَهُمَا ، فَإِنْ حَدَثَ بِهِمَا حَدَثٌ مِنْ عُهْدَةِ السَّنَةِ ، أَخَذَ ذَهَبَهُ مِنْ صَاحِبِهِ الَّذِي ابْتَاعَ مِنْهُ، فَهَذَا لَا بَأْسَ بِهِ، وَبِهَذَا مَضَتِ السُّنَّةُ فِي بَيْعِ الرَّقِيقِ","امام مالک رحمہ اللہ نے فرمایا: ان دونوں صورتوں میں فرق کرنے والی چیز قبضے میں لے لینا ہے۔ (چنانچہ) جس شخص نے اس چیز کو قبضے میں لے لیا جسے اس نے اجرت پر یا کرائے پر لیا ہے تو وہ دھوکے سے نکل آئے گا اور اس سلف (ادھار) سے بھی جو کہ مکروہ ہے، اور وہ ایک معلوم و متعین چیز لے لے گا اور بلاشبہ اس (قبضے والی جائز صورت) کی مثال تو یوں ہے کہ آدمی غلام یا لونڈی کو خرید لے اور اسے قبضے میں کر لے اور ان کی قیمت بھی نقد ادا کر دے، پھر اگر سال کی ذمہ داری میں ان دونوں پر کوئی حادثہ پیش آگیا (یعنی ان میں عیب نہ ہونے کی ذمہ داری بائع کی تھی اور سال بھر کی گارنٹی تھی لیکن سال پورا ہونے سے قبل ان میں عیب نظر آگیا) تو وہ اپنے اس ساتھی سے اپنا سونا وصول کر لے گا جس سے اس نے خریداری کی تھی (اور غلام لونڈی کو واپس لوٹا دے گا) تو یہ ایسی صورت ہے جس میں کوئی حرج نہیں اور غلاموں لونڈیوں کی بیع میں اس کے مطابق سنت جاری ہے۔","قَالَ مَالِكٌ : وَمَنِ اسْتَأْجَرَ عَبْداً بِعَيْنِهِ ، أَوْ تَكَارَى رَاحِلَةً بِعَيْنِهَا ، إِلَى أَجَلٍ ، يَقْبِضُ الْعَبْدَ، أَوِ الرَّاحِلَةَ إِلَى ذَلِكَ الْأَجَلِ ، فَقَدْ عَمِلَ بِمَا لَا يَصْلُحُ ، لَا هُوَ قَبَضَ مَا اسْتَكْرَى ، أَوِ اسْتَأْجَرَ، وَلَا هُوَ سَلَّفَ فِي دَيْنٍ يَكُونُ ضَامِناً عَلَى صَاحِبِهِ حَتَّى يَسْتَوْفِيَهُ.","امام مالک رحمہ اللہ نے فرمایا: اور جس شخص نے کوئی متعین غلام اجرت پر لیا یا کسی معین اونٹ کو کرائے پر لیا اور اس کی وصولی کے لیے ایک مدت تک تاخیر کی کہ وہ اس مدت میں غلام یا اونٹ کو قبضے میں لے گا تو یقیناً اس نے ایسا عمل کیا جو درست نہیں ہے، نہ تو اس نے اس چیز کو قبضے میں لیا ہے جسے کرائے پر یا اجرت پر لیا تھا اور نہ ہی اس (مستاجر ومستکری یعنی اجرت وکرائے پر لینے والے) نے کسی ایسے دین (قرض والے سودے) میں پیشگی ادائیگی کی ہے جو اس کے ساتھی (مؤخر یعنی چیز کے مالک) کی ضمانت میں رہتا، یہاں تک کہ وہ اسے اس سے پورا پورا لیتا۔","......: یہ بھی دراصل گزشتہ مسئلے کا حصہ ہے اور یہاں اس ممنوع صورت کی علت بیان کی جا رہی ہے کہ یہ صورت نہ تو اجرت وکرائے والی بنتی ہے اور نہ ہی بیع سلف والی، بیع سلف میں یوں ہوتا ہے کہ مشتری نقد رقم ادا کرتا ہے اور بائع ایک طے شدہ مدت پر متعین چیز ادا کرتا ہے، ایک طرف عین (نقد) اور دوسری طرف دین (قرض) ہوتا ہے، اور چیز کی ادائیگی بائع پر قرض رہتی ہے اور اس مدت کا وہی ضامن ہوتا ہے جبکہ مذکورہ صورت میں کچھ خریدا ہی نہیں گیا۔"],"454":["§خلاصۃ الباب","اس باب میں کوئی روایت نہیں ہے، صرف امام مالک رحمہ اللہ کا ایک فتویٰ مذکور ہے۔","......: ’’ثمر‘‘ ہر قسم کے پھل پر بولا جاتا ہے جبکہ ’’فاکہہ‘‘ سے مراد وہ پھل ہیں جو کھجور اور انار کے علاوہ ہیں، بعض نے انگور کو بھی فاکہہ میں شامل نہیں کیا، اسی طرح فاکہہ کے معنی صرف خشک پھل یا لذیذ پھل کے بھی کیے گئے ہیں۔","قَالَ مَالِكٌ : الْأَمْرُ الْمُجْتَمَعُ عَلَيْهِ عِنْدَنَا : أَنَّ مَنِ ابْتَاعَ شَيْئاً مِنَ الْفَاكِهَةِ مِنْ رَطْبِهَا ، أَوْ يَابِسِهَا ، فَإِنَّهُ لَا يَبِيعُهُ حَتَّى يَسْتَوْفِيَهُ، وَلَا يُبَاعُ شَيْءٌ مِنْهَا بَعْضُهُ بِبَعْضٍ إِلَّا يَداً بِيَدٍ، وَمَا كَانَ مِنْهَا مِمَّا يَيْبَسُ, فَيَصِيرُ فَاكِهَةً يَابِسَةً","امام مالک رحمہ اللہ نے فرمایا: ہمارے ہاں اس حکم پر اجماع ہے کہ جس شخص نے کسی قسم کا پھل خریدا، تر یا خشک، تو بلاشبہ وہ اسے (آگے) نہ بیچے، یہاں تک کہ اسے پورا پورا اپنے قبضے میں لے لے، اور ان میں سے کوئی بھی چیز ایک دوسری کے عوض نہ بیچی جائے، مگر صرف اور صرف نقد ونقد (ہی تُدَّخَرُ وَتُؤْكَلُ، فَلَا يُبَاعُ بَعْضُهُ بِبَعْضٍ إِلَّا يَداً بِيَدٍ، وَمِثْلاً بِمِثْلٍ، إِذَا كَانَ مِنْ صِنْفٍ وَاحِدٍ، فَإِنْ كَانَ مِنْ صِنْفَيْنِ مُخْتَلِفَيْنِ، فَلَا بَأْسَ بِأَنْ يُبَاعَ مِنْهُ اثْنَانِ بِوَاحِدٍ، يَداً بِيَدٍ, وَلَا يَصْلُحُ إِلَى أَجَلٍ، وَمَا كَانَ مِنْهُمَا مِمَّا لَا يَيْبَسُ وَلَا يُدَّخَرُ، وَإِنَّمَا يُؤْكَلُ رَطْباً، كَهَيْئَةِ الْبِطِّيخِ، وَالْقِثَّاءِ، وَالْخِرْبِزِ، وَالْجَزَرِ، وَالْأُتْرُجِّ، وَالْمَوْزِ، وَالرُّمَّانِ، وَمَا كَانَ مِثْلَهُ، وَإِنْ يَبِسَ لَمْ يَكُنْ فَاكِهَةً بَعْدَ ذَلِكَ، وَلَيْسَ هُوَ مِمَّا يُدَّخَرُ، وَيَكُونُ فَاكِهَةً قَالَ : فَأَرَاهُ حَقِيقاً أَنْ يُؤْخَذَ مِنْهُ مِنْ صِنْفٍ وَاحِدٍ، اثْنَانِ بِوَاحِدٍ، يَداً بِيَدٍ، فَإِذَا لَمْ يَدْخُلْ فِيهِ شَيْءٌ مِنَ الْأَجَلِ، فَإِنَّهُ لَا بَأْسَ بِهِ تبادلہ کرے) اور ان میں سے جو پھل خشک ہونے والے پھلوں میں سے ہو جو خشک میوہ بن جاتا ہے اور ذخیرہ کر لیا جاتا ہے اور خشک بھی کھایا جاتا ہے، تو ان میں سے کسی کو کسی کے بدلے نہ بیچا جائے مگر (دو شرطوں کے ساتھ یعنی) نقد ونقد اور برابر برابر (بشرطیکہ) جب وہ ایک ہی جنس سے ہو (کیونکہ جنس ایک ہو تو نہ ادھار جائز ہے اور نہ کمی بیشی)، ہاں اگر دو مختلف جنسیں ہوں تو پھر اس میں کوئی حرج نہیں کہ ان میں سے ایک کے بدلے دو کو نقد ونقد خریدا جائے، اور یہ (سودا کسی) میعاد تک درست نہیں ہے، (جنس الگ الگ ہو تو ادھار ناجائز ہے اور کمی بیشی جائز ہے) اور ان میں سے جو پھل خشک (استعمال) نہ ہوتا ہو اور نہ ذخیرہ کیا جاتا ہو اور یقیناً اسے تو صرف تر ہی کھایا جاتا ہے مثلاً تربوز، ککڑی، (کھیرا)، خربوزہ، مالٹا، کیلا، گاجر، انار اور جو کوئی بھی ان جیسا پھل ہو، اور اگر وہ خشک ہو جائے تو وہ اس خشک ہونے کے بعد پھل ہی نہیں رہتا (بلکہ خراب اور ضائع ہو جاتا ہے، اور وہ ان پھلوں جیسا نہ ہو جنھیں ذخیرہ بھی کیا جائے تو وہ میوہ ہی رہتا ہے۔ امام مالک رحمہ اللہ نے فرمایا: تو میں (صرف تر حالت میں استعمال ہونے والے) اس پھل کو اس لائق سمجھتا ہوں کہ ایک ہی جنس (کے ایسے پھلوں کا باہمی تبادلہ ہو تو ان میں) سے ایک کے بدلے دو کو نقد ونقد لیا جا سکتا ہے (یعنی کمی بیشی تو درست ہے لیکن ادھار ناجائز ہے) امام مالک رحمہ اللہ نے فرمایا: جب اس میں کسی مدت تک کی کچھ تاخیر داخل نہ ہو (بلکہ دونوں جانب سودا نقد ونقد ہو) تو بلاشبہ اس میں کوئی حرج نہیں ہے۔","......: رسول اللہ صلی اللہ علیہ وسلم نے چھ چیزوں کا نام لے کر فرمایا تھا کہ ان میں سے ہر جنس کا آپس میں تبادلہ ہو تو ان کا نقد ونقد اور برابر برابر ہونا لازم ہے، ہاں اگر جنس تبدیل ہو تو پھر نقد ونقد ہونا تو لازم ہے اور وزن میں کمی بیشی کی اجازت ہے، وہ چھ چیزیں یہ ہیں: سونا، چاندی، گندم، جو، کھجور اور نمک۔ (بخاری: ۲۱۳۴، مسلم: ۱۵۸۴، ۱۵۸۷) ان چھ اشیاء کے متعلق تو فقہاء کا اتفاق ہے، البتہ باقی اجناس اور نقدیوں کے متعلق اختلاف ہے، چنانچہ اہل ظاہر، ابن حزم، بغوی، نواب صدیق حسن خان اور شوکانی رحمہم اللہ وغیرہ کے نزدیک ان چھ اشیاء کے علاوہ کہیں بھی یہ پابندیاں نہیں ہیں، امام ابوحنیفہ، امام احمد رحمہما اللہ اور جمہور کے نزدیک رسول اللہ صلی اللہ علیہ وسلم نے ان چھ چیزوں کا نام بطور مثال لیا تھا، اور جہاں جہاں ان اشیاء جیسی علت سود پائی جائے گی وہاں سود کا حکم لگے گا، امام مالک رحمہ اللہ نے اسے صرف ذخیرہ ہونے والی خوراک کے ساتھ خاص کیا ہے۔ ہمارے نزدیک راجح موقف کی تفصیل یہ ہے کہ خوردنوش سے تعلق رکھنے والی تمام اشیاء خواہ وہ صرف تر حالت میں استعمال ہوں یا خشک بھی اور تر بھی یا صرف خشک مستعمل ہوں، اور اسی طرح ہر قسم کی نقدی اور کرنسی میں یہی حکم ہے، چنانچہ جب خوراک سے متعلقہ اجناس کا تبادلہ ہو اور دونوں جانب ایک ہی جنس ہو تو نقد ونقد اور برابری کی شرط ہے، اگر ادھار ہوا یا کمی بیشی ہوئی تو یہ دونوں سود شمار ہوں گے، اسی طرح ہم جنس نقدی وکرنسی مثلاً سونے کے بدلے سونا وغیرہ ہو تو اس کے تبادلے میں بھی مذکورہ دونوں شرطیں ہیں، ہاں اگر خوردنوش والی اشیاء میں جنس تبدیل ہو، مثلاً گندم کے بدلے جو، یا الگ الگ قسم کی نقدی کا باہم تبادلہ ہو، مثلاً سونے کے بدلے چاندی تو پھر صرف ایک شرط ہے کہ نقد ونقد تبادلہ ہو، اگر ادھار کر لیا تو اس پر سود کا حکم لگے گا، ہاں وزن کی کمی بیشی جائز ہے، رہی یہ صورت کہ ایک طرف کھانے پینے کی کوئی جنس ہو اور دوسری طرف اس کے بدلے میں کوئی نقدی ہو، مثلاً سونے کے بدلے گندم وغیرہ تو پھر کوئی شرط نہیں ہے، ادھار بھی درست ہے اور کمی بیشی بھی۔ اسی طرح جاندار اشیاء مثلاً غلام کے بدلے غلام وغیرہ میں بھی کوئی شرط نہیں ہے، نیز دیگر مصنوعات اور ایجادات میں بھی ایسی کوئی شرط نہیں ہے۔ واللہ اعلم"],"455":["§خلاصۃ الباب","اس باب میں گیارہ روایات ہیں، چھ مرفوع (احادیث نبویہ) ہیں، جن میں سے چار صحیح اور دو ضعیف ہیں، تین موقوف (آثار صحابہ) ہیں جن میں سے دو صحیح ہیں اور ایک ضعیف ہے اور دو مقطوع (آثار تابعین) ہیں جو سنداً صحیح ہیں، نیز امام مالک رحمہ اللہ کے دو فتاویٰ بھی اس باب میں مذکور ہیں۔","......: سونا اور چاندی دنیا میں اصل نقدیاں تصور کیے جاتے ہیں، آج کل رائج کاغذی نوٹ والی کرنسیاں دراصل سونے کی قیمت کا بدل اور اس کی رسید شمار ہوتی ہیں۔ سونا اگر دیناروں، اشرفیوں اور سکوں کی صورت میں ڈھال لیا جائے تو اسے ’’عین‘‘ (نقدی) کہتے ہیں، اور اگر خام حالت میں ڈلی ہی کی شکل میں ہو تو اسے ’’تبر‘‘ کہتے ہیں۔ اسی طرح چاندی کو درہموں یا سکوں میں ڈھال لیں تو اسے عین (نقدی) کہتے ہیں اور وہ ڈھلی ہوئی نہ ہو تو اسے ’’تبر‘‘ کہتے ہیں۔ سونے چاندی کا استعمال برتنوں اور زیورات وغیرہ میں عام ہوتا ہے، چنانچہ سونا اور چاندی کسی بھی حالت میں ہوں ان کی خرید وفروخت میں جب دونوں جانب سونا ہو یا چاندی ہو تو دونوں جانب برابری بھی لازم ہے اور نقد ونقد ہونا بھی۔ اور اگر اس تبادلے میں کسی جانب اضافہ کر دیا جائے خواہ سونا یا چاندی ہی کی شکل ہو یا کسی اور چیز کے نفع کی صورت میں تو یہ سراسر سود ہے۔ یاد رہے کہ سونا اور چاندی، خواہ عمدہ ہو یا گھٹیا، مضروب یعنی کسی شکل میں ڈھلا ہوا ہو یا غیر مضروب ہو یعنی ڈلی کی صورت میں ہو، زیور ہو یا برتن یا سکے کی شکل میں ہو، خالص ہو یا ملاوٹ شدہ، کھوٹا ہو یا کھرا، اکیلا ہو یا کسی چیز کے ساتھ ملا ہوا، ہر صورت میں باہمی تبادلہ کرتے وقت وزن برابر ہونا اور نقد ونقد ہونا لازم ہے، اگر ایسا کرنے میں کسی کو خسارے کا اندیشہ ہو تو وہ اپنے سونے کو کسی اور چیز کے بدلے میں بیچ ڈالے اور پھر اس چیز کے بدلے اپنا مطلوبہ سونا خرید لے۔"],"456":["§خلاصۃ الباب","اس باب میں ایک مرفوع روایت (حدیث نبوی) ہے جو بخاری ومسلم میں بھی موجود ہے، نیز امام مالک رحمہ اللہ کا ایک فتویٰ بھی مذکور ہے۔","سونے کے بدلے چاندی یا چاندی کے بدلے سونا لینا ’’بیع صرف‘‘ کہلاتا ہے، بڑے سکوں کا چھوٹے سکوں کے ساتھ تبادلہ بھی ’’صرف‘‘ کہلاتا ہے، بیع صرف کو کرنسی چینج کرانا، نوٹ بھنانا، تبادلہ رقم اور تبدیلی سکہ وغیرہ سے بھی تعبیر کرتے ہیں۔"],"457":["§خلاصۃ الباب","اس باب میں ایک مقطوع روایت (اثر تابعی) ہے جو سنداً صحیح ہے اور امام مالک رحمہ اللہ کے چھ فتاویٰ بھی اس باب میں مذکور ہیں۔","سونے کو سونے کے بدلے اور چاندی کو چاندی کے بدلے تول کر بیچنا ’’مراطلہ‘‘ کہلاتا ہے۔"],"458":["§خلاصۃ الباب","اس باب میں سات روایات ہیں، تین مرفوع (احادیث نبویہ) ہیں جو بخاری ومسلم میں بھی موجود ہیں، تین موقوف (آثار صحابہ) ہیں جن میں سے ایک صحیح اور دو ضعیف ہیں، اور ایک مقطوع (اثر تابعی رحمہ اللہ) ہے جو سنداً صحیح ہے، نیز امام مالک رحمہ اللہ کا ایک فتویٰ بھی مذکور ہے۔","سیدنا ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «إِذَا تَبَايَعْتُمْ بِالْعِيْنَةِ وَأَخَذْتُمْ أَذْنَابَ الْبَقَرِ وَرَضِيْتُمْ بِالزَّرْعِ وَتَرَكْتُمُ الْجِهَادَ سَلَّطَ اللَّهُ عَلَيْكُمْ ذُلًّا لَا يَنْزِعُهُ حَتَّى تَرْجِعُوا إِلَى دِينِكُمْ» ’’جب تم بیع عینہ کرنے لگو گے، بیلوں کی دمیں پکڑ لو گے، کھیتی باڑی کے ساتھ راضی رہو گے اور جہاد چھوڑ بیٹھو گے تو اللہ تعالیٰ تم پر ایسی ذلت مسلط کر دیں گے جسے اس وقت تک دور نہیں فرمائیں گے جب تک کہ تم اپنے دین کی طرف نہ لوٹ آؤ۔‘‘ (ابوداود: ۳۴۶۲، احمد: ۲۷/۷، بیہقی: ۳۱۶/۵، اس کی سند صحیح ہے، الصحیحۃ: ۱۱) ’’بیع عینہ‘‘ یہ ہے کہ آدمی کوئی چیز کسی مقررہ قیمت کے ساتھ بیچے اور قیمت کی ادائیگی کے لیے ایک وقت مقرر کر دے، پھر اس میعاد سے قبل ہی خریدار سے وہ چیز کم قیمت میں خود خرید لے اور نقد ادائیگی کر دے، مثلاً ایک ماہ بعد ادائیگی کی میعاد مقرر کر کے ہزار روپے میں ایک کپڑا بیچا، پھر تھوڑی دیر مثلاً دو یا تین دن بعد خریدار کو آٹھ سو روپے نقد ادائیگی کر کے وہی کپڑا خود واپس خرید لیا، تو گویا خریدار کو آٹھ سو روپے نقد مل گئے اور ایک ماہ بعد ہزار روپے ادا کرنا اس کے ذمے ہو گیا، اس بیع میں ’’عینہ‘‘ وہی چیز اصل حالت میں مالک کو واپس مل جاتی ہے، اپنی چیز بعینہ واپس مل جانے ہی کی بنا پر اسے ’’عینہ‘‘ کہتے ہیں۔ یہ بیع اس لیے حرام ہے کہ یہ سود کے حصول کا ایک حیلہ وذریعہ ہے، بیع کا تو صرف نام ہی درمیان میں آتا ہے، ورنہ ہوا یوں ہے کہ خریدار کو پیسوں کی ضرورت تھی اور پیسے والا اسے سود پر قرض دینا چاہتا تھا لیکن سود پر پردہ ڈالنے کے لیے انھوں نے یہ گزشتہ صورت اختیار کی، اس بیع سے تھوڑی ہی دیر بعد خریدار کو آٹھ سو روپے نقد مل گئے جو کہ دراصل قرضہ ہے اور مہینے بعد وہ ہزار روپیہ لوٹائے گا جن میں سود کا دوسو روپیہ شامل ہوگا .... امام مالک، امام ابوحنیفہ، امام احمد رحمہ اللہ اور اہل حدیث کے ہاں یہ ’’بیع عینہ‘‘ حرام ہے لیکن امام شافعی رحمہ اللہ اسے جائز سمجھتے ہیں۔","امام مالک رحمہ اللہ کے نزدیک قبضے میں مال لینے سے پہلے آگے بیچنے کی ممانعت صرف اشیائے خورد ونوش اور اناج کے متعلق ہے۔ امام احمد رحمہ اللہ نے اسے صرف ماپ تول والی چیزوں کے ساتھ خاص کیا ہے۔ امام ابوحنیفہ رحمہ اللہ نے اسے تمام منقولہ اشیاء کے ساتھ مختص کیا ہے، جبکہ امام شافعی، امام احمد، امام زفر رحمہم اللہ اور اہل حدیث کے نزدیک ہر چیز میں یہ شرط ملحوظ رہے گی خواہ وہ وزنی، گیلی، عددی چیزیں ہوں یا غیر منقولہ جائداد وغیرہ کیونکہ سیدنا ابن عباس رضی اللہ عنہما سے بھی یہی منقول ہے۔ (بخاری: ۲۱۳۵، مسلم: ۱۵۲۵)"],"459":["§خلاصۃ الباب","اس باب میں تین مقطوع روایات (آثار تابعین) ہیں جو سنداً صحیح ہیں، نیز امام مالک رحمہ اللہ کے دو فتاویٰ بھی مذکور ہیں۔"],"460":["§خلاصۃ الباب","اس باب میں ایک موقوف روایت (اثر صحابی) ہے جو سنداً صحیح ہے، نیز امام مالک رحمہ اللہ کے چار فتاویٰ بھی مذکور ہیں۔","قیمت پیشگی ادا کر دینا اور متعین اناج کی وصولی کے لیے کوئی مدت مقرر کر لینا، بیع سلف یا بیع سلم کہلاتا ہے، اہل عراق کی لغت میں سلف جبکہ اہل حجاز کی لغت میں مسلم مستعمل ہے۔ دراصل یہ ایک معدوم چیز کی بیع ہوتی ہے، لیکن اقتصادی اور معاشی مصلحتوں کی بنا پر اسے مستثنیٰ قرار دیا گیا ہے، اس کی متعدد شروط بیان کی جاتی ہیں جن میں سے اہم اور ضروری دو ہیں: (۱) مطلوبہ چیز کا وزن یا ماپ معلوم ہو اور (۲) مدت بھی معلوم ہو۔۔۔۔۔ پھر کیا یہ بیع کرتے وقت مطلوبہ چیز کا بائع کے پاس موجود ہونا لازم ہے یا نہیں تو اس بارے میں صحابہ کرام رضی اللہ عنہم فرماتے ہیں کہ ہم اس کے متعلق پوچھتے بھی نہ تھے۔ (بخاری: ۲۲۴۴) جمہور کا یہی موقف ہے، نیز بیع سلف ہر چیز میں ہوسکتی ہے۔ (بخاری: ۲۲۴۰) امام مالک، امام شافعی اور امام احمد رحمہ اللہ کا یہی موقف ہے، البتہ امام ابوحنیفہ رحمہ اللہ کے نزدیک یہ بیع حیوانوں یعنی جانوروں اور غلاموں لونڈیوں میں ممنوع ہے۔ امام شوکانی رحمہ اللہ اور متعدد اہل حدیث علماء کا بھی یہی موقف ہے۔۔ یاد رہے کہ اس بیع میں قیمت کو ’’راس المال‘‘، مطلوبہ اناج وغیرہ کو ’’مسلم فیہ‘‘، بائع کو ’’مسلم الیہ‘‘ اور خریدار کو ’’رب السلم‘‘ کہتے ہیں۔"],"461":["§خلاصۃ الباب","اس باب میں تین روایات ہیں، ایک موقوف (اثر صحابی) ہے جو سنداً ضعیف ہے اور دو مقطوع (آثار تابعین) ہیں جن میں سے ایک صحیح اور ایک ضعیف ہے، نیز امام مالک رحمہ اللہ کے دس فتاویٰ جات بھی مذکور ہیں۔"],"462":["§خلاصۃ الباب","اس باب میں دو مقطوع روایات (آثار تابعین) ہیں جن میں سے ایک صحیح اور ایک ضعیف ہے، نیز امام مالک رحمہ اللہ کے آٹھ فتاویٰ جات بھی مذکور ہیں۔"],"463":["§خلاصۃ الباب","اس باب میں تین موقوف روایات (آثار صحابہ) ہیں جن میں سے دو ضعیف اور ایک سنداً صحیح ہے۔","اس عمل کو ’’احتکار‘‘ بھی کہتے ہیں۔ ذخیرہ اندوزی کرنے کی مختلف صورتیں ہیں جیسا کہ کوئی شخص اپنے سال بھر کے کھانے کے لیے یا آئندہ فصل کا بیج بونے کے لیے ذخیرہ کرے یا حاکم سال بھر ایک تناسب سے منڈی میں اشیاء مہیا کرنے کے لیے ذخیرہ کرے، ذخیرہ اندوزی کی ہر صورت ممنوع نہیں ہے، بلکہ صرف یہ شکل منع ہے کہ آدمی عوام اور خلق خدا کی شدید ضرورت یا قحط سالی کے انتظار میں مال ذخیرہ کر چھوڑے اور پھر منہ مانگے دام کمائے اور بلیک مارکیٹنگ کے ذریعے مال فروخت کرے۔"],"464":["§خلاصۃ الباب","اس باب میں تین روایات ہیں، دو موقوف (آثار صحابہ) ہیں جن میں سے ایک صحیح اور ایک ضعیف ہے اور ایک روایت مقطوع (اثر تابعی) ہے جس کی سند صحیح ہے، نیز امام مالک رحمہ اللہ کے اس میں پانچ فتاویٰ جات بھی مذکور ہیں۔","رسول اللہ صلی اللہ علیہ وسلم نے ایک غلام کا دو غلاموں کے عوض تبادلہ کیا۔ (صحیح مسلم: ۱۶۰۲) ایک غزوے کے لیے آپ صلی اللہ علیہ وسلم نے ادھار اونٹ لینے کا حکم دیا تو ایک اونٹ دو دو اونٹوں کے بدلے لیا گیا جن کی ادائیگی کا وقت زکاۃ کے اونٹوں کی آمد تک مؤخر کیا گیا۔ (ابوداود: ۳۳۵۷، احمد: ۱۷۱/۲، اس کی سند حسن ہے۔ ارواء الغلیل: ۱۳۵۸) یہ دونوں روایات واضح کر رہی ہیں کہ جانوروں کے باہمی تبادلے میں کمی بیشی بھی جائز ہے اور ادھار بھی، لیکن ایک روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حیوان کو حیوان کے بدلے ادھار فروخت کرنے سے منع فرمایا تھا۔ (ابوداود: ۳۳۵۶، ترمذی: ۱۲۳۷، ابن ماجہ: ۲۲۷۰، اس کی سند حسن ہے) امام ابوحنیفہ اور امام احمد رحمہما اللہ کے نزدیک یہ آخری روایت ناسخ ہے اور پہلی دونوں منسوخ ہیں اور جانوروں کی ادھار بیع منع ہے، لیکن جمہور کے نزدیک نسخ ثابت کرنے کے لیے تاریخ کا علم ہونا ضروری ہے جس سے یہ ثابت ہو کہ کون سی روایت پہلے کی ہے اور کون سی بعد کی، احتمالات سے نسخ ثابت نہیں ہوتا اور اصول حدیث کا مسلمہ قاعدہ بھی یہی ہے۔ لہذا جمہور ان روایات میں تطبیق دیتے ہیں۔ امام مالک، امام شافعی رحمہما اللہ اور اہل حدیث نے یوں تطبیق دی ہے کہ اگر دونوں جانب ادھار ہو تو بیع حرام ہے اور اگر ایک طرف ادھار ہو تو جائز ہے۔ جانوروں میں قرض اور ادھار کا بیان آگے باب: ۴۳ میں بھی آ رہا ہے، جمہور کے نزدیک اس کے جواز کی دلیل قتل خطا، قتل عمد اور قتل شبہ عمد کی دیتیں بھی ہیں جن میں قاتل کے خاندان پر سو اونٹ لازم ہوتے ہیں اور ادائیگی تک ان کے ذمے قرض رہتے ہیں خواہ اس میں کئی سال لگیں۔ حیرت ہے احناف پر کہ وہ حیوانات میں قرض کو جائز نہیں مانتے لیکن یہ اجازت دیتے ہیں کہ آقا اپنے غلام کو مکاتب بناتے وقت زر کتابت کسی معلوم شدہ جانور یا غلام یا لونڈی کی شکل میں متعین کر سکتا ہے، اور ظاہر بات ہے کہ مکاتب غلام جب تک اسے ادا نہ کرے گا وہ اس کے ذمے قرض رہے گا۔ اسی طرح احناف یہ بھی کہتے ہیں کہ حق مہر میں کوئی جاندار چیز متعین کی جاسکتی ہے اور وہ بھی ادائیگی تک خاوند کے ذمے قرض ہی رہے گی۔ لہذا حیوانات میں قرض تو خود احناف کی زبانی بھی ثابت ہو گیا۔ رہا کمی بیشی کا مسئلہ تو یہ بالاتفاق جائز ہے، البتہ امام مالک رحمہ اللہ کے نزدیک منافع کا یکساں نہ ہونا لازم ہے، چنانچہ جو کوئی سے دو جانور ایک جیسا نفع دیں تو ان کے تبادلے میں ان کے ہاں کمی بیشی درست نہیں اور اگر وہ الگ الگ منافع کے حامل ہوں تو پھر ایک کے بدلے کئی جانور بھی خریدے جا سکتے ہیں، لیکن جمہور کے ہاں ایسی کوئی شرط لازم نہیں ہے۔"],"465":["§خلاصۃ الباب","اس باب میں دو روایات ہیں، ایک مرفوع (حدیث نبوی) ہے جو بخاری ومسلم میں بھی ہے اور ایک مقطوع (اثر تابعی) ہے جو سنداً صحیح ہے، نیز امام مالک رحمہ اللہ کے دو فتاویٰ بھی مذکور ہیں۔"],"466":["§خلاصۃ الباب","اس باب میں تین روایات ہیں، ایک حدیث مرفوع (حدیث نبوی) ہے جو سنداً حسن ہے اور دو مقطوع (آثار تابعین) ہیں اور وہ بھی سنداً صحیح ثابت ہیں۔","زندہ جانور سے بھی اگر گوشت ہی مقصود ہو تو پھر بھی یہ بیع ناجائز رہے گی کیونکہ موجود گوشت کا وزن معلوم ہوتا ہے جبکہ زندہ جانور کے گوشت کا وزن غیر متعین اور نامعلوم ہوتا ہے، لہذا اس بیع میں دھوکا اور نقصان ہے۔"],"467":["§خلاصۃ الباب","اس باب میں کوئی روایت نہیں ہے، البتہ امام مالک رحمہ اللہ کے تین فتاویٰ جات مذکور ہیں۔","قَالَ مَالِكٌ: الْأَمْرُ الْمُجْتَمَعُ عَلَيْهِ عِنْدَنَا فِي لَحْمِ الْإِبِلِ وَالْبَقَرِ وَالْغَنَمِ وَمَا أَشْبَهَ ذَلِكَ مِنَ الْوُحُوشِ، أَنَّهُ لَا يُشْتَرَى بَعْضُهُ بِبَعْضٍ، إِلَّا مِثْلاً بِمِثْلٍ، وَزْناً بِوَزْنٍ، يَداً بِيَدٍ، وَلَا بَأْسَ بِهِ وَإِنْ لَمْ يُوزَنْ، إِذَا تَحَرَّى أَنْ يَكُونَ مِثْلاً بِمِثْلٍ، يَداً بِيَدٍ۔","امام مالک رحمہ اللہ نے فرمایا: ہمارے ہاں اونٹ، گائے، بھیڑ بکری یا ان کے مشابہ جنگلی جانوروں (ہرن، بارہ سنگھا، زیبرا وغیرہ) کے گوشت کے متعلق اس حکم پر اجماع ہے کہ بلا شبہ ان کو ایک دوسرے کے بدلے نہیں خریدا جا سکتا مگر ایک جیسا، برابر برابر اور نقد ونقد (جائز ہے) اور اس میں کوئی حرج نہیں، اگرچہ اسے تولا نہ جائے، جس وقت کہ اندازے سے یہ جستجو کی جائے کہ یہ (دونوں جانب کا گوشت) برابر برابر اور نقد ونقد ہے۔","یہ صرف امام مالک رحمہ اللہ کا موقف ہے کہ تمام گھریلو اور جنگلی جانوروں کے گوشت ایک ہی جنس سے تعلق رکھتے ہیں، جبکہ جمہور کے نزدیک ان میں سے ہر ہر نوع والا جانور الگ الگ حیثیت رکھتا ہے، چنانچہ اونٹ، گائے، بھینس کی جنسیں بھی الگ الگ ہیں، البتہ بھیڑ بکری اور دنبے کا گوشت ایک ہی جنس شمار ہوتا ہے۔ ہاں خرگوش، مرغی کی الگ اجناس ہیں، اور جنگلی جانور مثلاً ہرن، بارہ سنگھا وغیرہ کا گوشت بھی الگ الگ نوعیت کا ہے اور اسی وجہ سے سب کی قیمتوں میں فرق ہوتا ہے۔","قَالَ مَالِكٌ: وَلَا بَأْسَ بِلَحْمِ الْحِيتَانِ بِلَحْمِ الْإِبِلِ وَالْبَقَرِ وَالْغَنَمِ، وَمَا أَشْبَهَ ذَلِكَ مِنَ الْوُحُوشِ كُلِّهَا، اثْنَيْنِ بِوَاحِدٍ وَأَكْثَرَ مِنْ ذَلِكَ يَداً بِيَدٍ، فَإِنْ دَخَلَ ذَلِكَ الْأَجَلُ فَلَا خَيْرَ فِيهِ۔","امام مالک رحمہ اللہ نے فرمایا کہ مچھلیوں کے گوشت کو اونٹ، گائے اور بکری اور ان جیسے تمام جنگلی جانوروں کے گوشت کے عوض ایک کے بدلے دو یا اس سے بھی زیادہ لینے میں کوئی حرج نہیں ہے، اگر نقد ونقد ہو، چنانچہ اگر اس میں میعاد (ادھار) کا دخل ہو گیا تو پھر اس میں کوئی خیر نہیں ہے۔","گویا خشکی کے جانوروں کا گوشت امام مالک رحمہ اللہ کے نزدیک ایک ہی جنس ہے، پانی کے جانور یعنی مچھلیوں کا گوشت دوسری الگ جنس ہے، جن میں کمی بیشی سے تبادلہ جائز ہے، صرف نقد ونقد ہونا ضروری ہے، اور تیسری جنس یعنی فضا والے پرندوں کا گوشت تیسری جنس ہے، جیسا کہ آگے آ رہا ہے۔","قَالَ مَالِكٌ: وَأَرَى لُحُومَ الطَّيْرِ كُلَّهَا مُخَالِفَةً لِلُحُومِ الْأَنْعَامِ وَالْحِيتَانِ، فَلَا أَرَى بَأْساً بِأَنْ يُشْتَرَى بَعْضُ ذَلِكَ بِبَعْضٍ مُتَفَاضِلاً يَداً بِيَدٍ، وَلَا يُبَاعُ شَيْءٌ مِنْ ذَلِكَ إِلَى أَجَلٍ۔","امام مالک رحمہ اللہ نے فرمایا: میں تمام پرندوں کے گوشت کو چوپایوں اور مچھلیوں کے گوشت سے مختلف سمجھتا ہوں، لہذا میں اس میں کوئی حرج محسوس نہیں کرتا کہ انھیں ایک دوسرے کے بدلے کمی بیشی سے نقد ونقد خریدا جائے اور ان میں سے کسی بھی چیز کو کسی میعاد تک نہ بیچا جائے۔","لیکن جمہور کے نزدیک خشکی و تری اور فضا کے جانور ہزاروں اقسام واجناس پر مشتمل ہیں، ہر کسی کا الگ الگ بھاؤ ہے، لہذا جو بھی جنس تبدیل ہو تو کمی بیشی سے تبادلہ درست ہے، بلکہ اہل ظاہر اور بہت سے اہل حدیث علماء کے نزدیک تو ان کے باہمی تبادلے میں کوئی بھی پابندی نہیں، کمی بیشی بھی جائز ہے اور ادھار بھی، کیونکہ ان کے نزدیک کمی بیشی اور ادھار والا سود صرف چھ اشیاء تک محدود ہے، جن کا احادیث میں نام آیا ہے، لیکن راجح موقف جمہور کا ہے جو باقی اشیاء کو بھی ان پر قیاس کرتے ہیں۔ واللہ اعلم"],"468":["§خلاصۃ الباب","اس باب میں ایک مرفوع روایت یعنی حدیث نبوی ہے جو بخاری ومسلم میں بھی موجود ہے، نیز امام مالک رحمہ اللہ کا ایک فتویٰ بھی مذکور ہے۔","رسول اللہ صلی اللہ علیہ وسلم سے تین قسم کے کتوں کو پالنے کی اجازت ثابت ہے، شکار کے لیے، کھیتی کی حفاظت کے لیے اور جانوروں کی حفاظت کے لیے۔ (بخاری: ۲۳۲۲، ۵۴۸۰، مسلم: ۱۵۷۱، ۱۵۷۵) گھر کی حفاظت یا سراغ رسانی میں امن کی حفاظت کے لیے جاسوس کتوں کو بھی انھی پر قیاس کیا جائے گا، ان کے علاوہ ہر کتا پالنے والے کے اجر سے روزانہ ایک قیراط یا دو قیراط کم کرنے کا باعث بنتا ہے۔ (بخاری ومسلم، حوالہ مذکور)"],"469":["§خلاصۃ الباب","اس باب میں ایک حدیث نبوی ہے جو سنداً صحیح ہے، نیز امام مالک رحمہ اللہ کے چار فتاویٰ جات بھی مذکور ہیں۔"],"470":["§خلاصۃ الباب","اس باب میں ایک موقوف روایت (اثر صحابی) ہے جو سنداً صحیح ہے، نیز امام مالک رحمہ اللہ کے سات فتاویٰ جات بھی مذکور ہیں۔","جمہور کے نزدیک ہر چیز میں بیع سلف ہو سکتی ہے جبکہ احناف اور بعض دیگر علماء کے نزدیک جانوروں کے علاوہ ہر چیز میں ہو سکتی ہے۔"],"471":["§خلاصۃ الباب","اس باب میں کوئی روایت نہیں ہے، البتہ امام مالک رحمہ اللہ کے چار فتاویٰ جات مذکور ہیں۔","قَالَ مَالِكٌ : الأَمْرُ عِنْدَنَا فِيمَا كَانَ مِمَّا يُوزَنُ، مِنْ غَيْرِ الذَّهَبِ وَالْفِضَّةِ مِنَ النُّحَاسِ وَالشَّبَهِ وَالرَّصَاصِ وَالآنْكِ وَالْحَدِيدِ وَالْقَضْبِ وَالتِّينِ وَالْكُرْسُفِ، وَمَا أَشْبَهَ ذَلِكَ مِمَّا يُوزَنُ، فَلَا بَأْسَ بِأَنْ يُؤْخَذَ مِنْ صِنْفٍ وَاحِدٍ اثْنَانِ بِوَاحِدٍ ، يَداً بِيَدٍ، وَلَا بَأْسَ أَنْ يُؤْخَذَ رِطْلُ حَدِيدٍ بِرِطْلَىْ حَدِيدٍ ، وَرِطْلُ صُفْرٍ بِرِطْلَىْ صُفْرٍ.","امام مالک رحمہ اللہ نے فرمایا: ہمارے ہاں حکم یہ ہے کہ سونے اور چاندی کے علاوہ وہ تمام چیزیں جن کا وزن کیا جاتا ہے مثلاً تانبا، پیتل، رانگ (قلعی)، سیسہ، لوہا، برسیم حجازی (یا درختوں کے پتے)، انجیر، روٹی اور ان کے مشابہ دوسری اشیاء جن کا تعلق وزن سے ہے، تو اس میں کوئی حرج نہیں کہ ان میں سے ایک ہی صنف میں ایک کے بدلے دو کو نقد ونقد لیا جائے، (کمی بیشی جائز ہے اور ادھار ناجائز)، چنانچہ اس میں کوئی حرج نہ ہوگا کہ لوہے کا ایک رطل (وزن کرنے کا ایک پیمانہ جو چھ چھٹانک تین تولے اور نو ماشے کا ہوتا ہے یعنی ۳۹۳-۶۰۰ گرام) لوہے ہی کے دو رطلوں کے عوض یا پیتل کا ایک رطل (پیتل ہی کے) دو رطلوں کے عوض لے لیا جائے۔","قَالَ مَالِكٌ : وَلَا خَيْرَ فِيهِ اثْنَانِ بِوَاحِدٍ مِنْ صِنْفٍ وَاحِدٍ إِلَى أَجَلٍ ، فَإِذَا اخْتَلَفَ الصِّنْفَانِ مِنْ ذَلِكَ فَبَانَ اخْتِلَافُهُمَا ، فَلَا بَأْسَ بِأَنْ يُؤْخَذَ مِنْهُ اثْنَانِ بِوَاحِدٍ إِلَى أَجَلٍ، فَإِنْ كَانَ الصِّنْفُ مِنْهُ يُشْبِهُ الصِّنْفَ الآخَرَ","ہاں اس میں کوئی خیر نہیں کہ ایک ہی صنف کی چیز میں سے ایک کے بدلے دو کو ادھار لیا جائے۔ پھر جب ان میں سے دو اضاف (اقسام) مختلف ہوں اور ان کا مختلف ہونا واضح ہو تو ان میں سے ایک کے بدلے دو کو ادھار لینے میں کوئی حرج نہیں، اور اگر ان میں سے ایک صنف دوسری وَإِنِ اخْتَلَفَا فِي الاِسْمِ، مِثْلُ الرَّصاصِ وَالاَنْكِ، وَالشَّبَهِ وَالصُّفْرِ، فَإِنِّى أَكْرَهُ أَنْ يُؤْخَذَ مِنْهُ اثْنَانِ بِوَاحِدٍ إِلَى أَجَلٍ .","صنف کے مشابہ ہو، اگر چہ ان کے نام مختلف ہی ہوں، مثلاً رانگ (قلعی) اور سیسہ، یا شبہ (انتہائی عمدہ تانبا) اور صفر (خالص تانبا)، تو یقیناً میں یہ ناپسند کرتا ہوں کہ ان میں سے ایک کے بدلے دو کو ادھار لیا جائے۔","ہمارے نزدیک ہر چیز خواہ اس کا تعلق وزن سے ہو یا ماپ سے ہو یا عدد سے ہو، ان تمام میں جب ہم جنس چیز کے بدلے تبادلہ ہو تو نہ کمی بیشی جائز ہے اور نہ ادھار، اور اگر تبادلہ کرنا ہی ہو تو ان میں سے ایک چیز کو پیسوں کے عوض بیچ کر دوسری کو پیسوں کے عوض خریدنا چاہیے۔ ’’نحاس‘‘ تانبے کو کہتے ہیں، اسے ملاوٹوں سے خالص کر کے عمدہ بنا لیں تو ’’صفر‘‘ کہلاتا ہے اور اس قدر عمدہ اور اعلیٰ کوالٹی کو پہنچ جائے کہ سونے کے مشابہ ہو جائے تو ’’شبہ‘‘ کہلاتا ہے، عام طور پر صفر اور شبہ کے معنی پیتل کے کیے جاتے ہیں، اسی طرح رصاص (قلعی، رانگ، رانگا) کو خالص کر لیا جائے تو وہ ’’آنک‘‘ (سیسہ) بن جاتا ہے۔","قَالَ مَالِكٌ : وَمَا اشْتَرَيْتَ مِنْ هَذِهِ الأَصْنَافِ كُلِّهَا ، فَلَا بَأْسَ أَنْ تَبِيعَهُ قَبْلَ أَنْ تَقْبِضَهُ مِنْ غَيْرِ صَاحِبِهِ الَّذِي اشْتَرَيْتَهُ مِنْهُ ، إِذَا قَبَضْتَ ثَمَنَهُ ، إِذَا كُنْتَ اشْتَرَيْتَهُ كَيْلاً أَوْ وَزْناً ، فَإِنِ اشْتَرَيْتَهُ جِزَافاً فَبِعْهُ مِنْ غَيْرِ الَّذِي اشْتَرَيْتَهُ مِنْهُ بِنَقْدٍ أَوْ إِلَى أَجَلٍ ، وَذَلِكَ أَنَّ ضَمَانَهُ مِنْكَ إِذَا اشْتَرَيْتَهُ جِزَافاً ، وَلَا يَكُونُ ضَمَانُهُ مِنْكَ إِذَا اشْتَرَيْتَهُ وَزْناً حَتَّى تَزِنَهُ وَتَسْتَوْفِيَهُ، وَهَذَا أَحَبُّ مَا سَمِعْتُ إِلَيَّ فِي هَذِهِ الأَشْيَاءِ كُلِّهَا ، وَهُوَ الَّذِى لَمْ يَزَلْ عَلَيْهِ أَمْرُ النَّاسِ عِنْدَنَا.","امام مالک رحمہ اللہ نے فرمایا: اور تم ان تمام اصناف میں سے جسے بھی خرید لو تو اس میں کوئی حرج نہ ہوگا کہ اسے قبضے میں لینے سے پہلے ہی کسی ایسے شخص کو بیچ دو جو ان چیزوں کے (پرانے) مالک کے علاوہ ہو جس سے کہ تم نے اسے خریدا تھا، (بشرطیکہ) جب تم اس کی قیمت نقد وصول کر لو (اور یہ بھی شرط ہے کہ) جب تم نے خود اس چیز کو ماپ یا تول کے حساب سے خریدا ہوا تھا، چنانچہ جب تم نے اسے اندازے سے خریدا ہو تو پھر تم اسے اس شخص جس سے تم نے خریدا ہے، کے علاوہ کسی اور کو نقد (قیمت لے کر) بھی بیچ سکتے ہو اور ادھار بھی۔ اور یہ (فرق) اس وجہ سے ہے کہ جب تم اندازے سے اس (ڈھیری) کو خریدو گے تو بلا شبہ اس چیز کی ضمانت تمھاری طرف سے ہو جائے گی اور جب تم نے اسے وزن یا ماپ کی صورت میں خریدا ہو تو اس کی ضمانت تمھاری طرف سے نہیں ہوگی یہاں تک کہ تم اس چیز کو تول لو اور اسے پورا پورا وصول کر لو۔ اور یہی میرے نزدیک وہ سب سے زیادہ پسندیدہ بات ہے جو میں نے ان تمام چیزوں کے متعلق (علماء سے) سنی ہے اور ہمارے ہاں ہمیشہ سے لوگوں کا یہی معاملہ (چلا آ رہا) ہے۔","خریدار، بائع سے وزن یا ماپ طے کر کے کسی چیز کو خرید لے تو جب تک وہ اس کو ماپ تول کر اور تسلی کر کے قبضے میں نہ لے لے گا وہ اس کا ضامن نہیں بنے گا، اور چونکہ یہ چیزیں کھانے پینے سے تعلق نہیں رکھتیں اس لیے امام مالک رحمہ اللہ کے نزدیک انھیں قبضے میں لینے سے پہلے بھی بیچنا جائز ہے لیکن ابھی ضمانت میں نہ آسکنے کی وجہ سے وہ اسے صرف نقد قیمت لے کر آگے بیچنے کی اجازت دیتے ہیں تا کہ نیا سودا کرتے وقت ادھار کے بدلے ادھار نہیں ہو، کیونکہ خریدار کے پاس جب سامان قبضے ہی میں نہ آیا ہو تو اس کی جانب سودا نقد موجود نہ ہوگا، البتہ جب وہ اس ادھار مال کو آگے بیچے اور قیمت نقد وصول کر لے تو دونوں جانب ادھار کی صورت نہ بنے گی، لہذا یہ بیع جائز ہوگی...... ہاں جب وہ چیز اس کے قبضے میں آ جائے گی تو وہ ضامن بن جائے گا، اب چونکہ اس کے پاس وہ چیز نقد موجود ہے اس لیے وہ اسے آگے بیچتے وقت ادھار کر سکتا ہے، اس کی جانب نقد مال ہوگا اور خریدار کی طرف ادھار، تو یہ بھی درست ہے...... رہی یہ صورت کہ کسی ڈھیر کو تخمینہ واندازہ لگا کر خرید لیا جائے تو اسے ماپے تولے بغیر ہی بندہ اس کا مالک اور ضامن بن جاتا ہے اور وہ اس کے پاس نقد موجود سمجھی جاتی ہے، لہذا اسے آگے بیچنا ہو تو نئے سودے میں خواہ نقد قیمت وصول کی جائے یا ادھار، دونوں جائز ہیں کیونکہ اس صورت میں ادھار کے بدلے ادھار لازم نہیں آتا۔","قَالَ مَالِكٌ : الأَمْرُ عِنْدَنَا فِيمَا يُكَالُ أَوْ يُوزَنُ، مِمَّا لَا يُؤْكَلُ ، وَلَا يُشْرَبُ، مِثْلُ الْعُصْفُرِ وَالنَّوَى وَالْخَبَطِ وَالْكَتَمِ ، وَمَا يُشْبِهُ ذَلِكَ، أَنَّهُ لَا بَأْسَ بِأَنْ يُؤْخَذَ مِنْ كُلِّ صِنْفٍ مِنْهُ اثْنَانِ بِوَاحِدٍ ، يَداً بِيَدٍ، وَلَا يُؤْخَذُ مِنْ صِنْفٍ وَاحِدٍ مِنْهُ اثْنَانِ بِوَاحِدٍ إِلَى أَجَلٍ ، فَإِنِ اخْتَلَفَ الصِّنْفَان فَبَانَ اخْتِلافُهُمَا ، فَلَا بَأْسَ بِأَنْ يُؤْخَذَ مِنْهُمَا اثْنَانِ بِوَاحِدٍ إِلَى أَجَلٍ، وَمَا اشْتُرِيَ مِنْ هَذِهِ الأَصْنَافِ كُلِّهَا ، فَلَا بَأْسَ بِأَنْ يُبَاعَ قَبْلَ أَنْ يُسْتَوْفَى، إِذَا قَبَضَ ثَمَنَهُ مِنْ غَيْرِ صَاحِبِهِ الَّذِي اشْتَرَاهُ مِنْهُ.","امام مالک رحمہ اللہ نے فرمایا: وہ چیزیں جنھیں ماپا یا تولا جاتا ہے لیکن کھایا پیا نہیں جاتا، مثلاً کسم (وہ پودا جس کے پھول کپڑے رنگنے میں استعمال ہوتے ہیں)، گٹھلیاں، جھاڑے ہوئے پتے، کتم (وہ پودا جو لکھنے کی روشنائی بنانے اور بالوں کو رنگنے کے لیے خضاب بنانے میں استعمال ہوتا ہے) اور جو کوئی ان کے مشابہ چیز ہو تو ان کے متعلق ہمارے ہاں یہ حکم ہے کہ ان میں سے کسی بھی قسم میں سے ایک کے بدلے دو کو نقد ونقد لینے میں کوئی حرج نہیں اور ایک ہی صنف سے ایک کے بدلے دو کو ادھار نہ لیا جائے۔ پھر اگر دو اصناف باہم مختلف ہوں اور ان کا مختلف ہونا واضح ہو تو پھر ان میں سے ایک کو دو کے بدلے ادھار لینے میں بھی کوئی حرج نہیں ہے...... اور ان تمام اصناف میں سے جس چیز کو بھی خرید لیا جائے تو اسے قبضے میں لینے سے پہلے ہی آگے بیچ دینے میں بھی کوئی حرج نہیں ہے (بشرطیکہ) اس کی قیمت قبضے میں لے لے (تا کہ ادھار کی ادھار سے بیچ والی صورت نہ بنے اور دوسری شرط یہ ہے کہ یہ نیا سودا) اپنے ساتھی جس سے آدمی نے یہ چیز خریدی ہو یعنی بائع کے علاوہ کسی اور سے (کرے، کیونکہ اسی بائع سے تو ابھی اپنا یہ مال قبضے میں لینا ہے اور اگر اس سے وصول کیے بغیر ہی اس کو واپس بیچ دیا جائے تو کئی خرابیاں یا پابندیاں لازم آتی ہیں)۔","قَالَ مَالِكٌ : وَكُلُّ شَيْءٍ يَنْتَفِعُ بِهِ النَّاسُ مِنَ الأَصْنَافِ كُلَّهَا ، وَإِنْ كَانَتِ الْحَصْبَاءَ وَالْقَصَّةَ ، فَكُلُّ وَاحِدٍ مِنْهُمَا بِمِثْلَيْهِ إِلَى أَجَلٍ، فَهُوَ رِباً ، وَوَاحِدٌ مِنْهُمَا بِمِثْلِهِ وَزِيَادَةٌ شَيْءٍ مِنَ الأَشْيَاءِ إِلَى أَجَلٍ ، فَهُوَ رِباً.","امام مالک رحمہ اللہ نے فرمایا: اور تمام قسم کی اصناف میں سے جس چیز سے بھی لوگ نفع اٹھاتے ہیں، اگر چہ وہ کنکریاں اور چونا ہی ہوں، ان میں سے کوئی بھی چیز اس کی دو مثل (دوگنا) کے ساتھ ادھار (کر کے بیچنا، خریدنا) سود ہے اور اسی طرح کنکریوں اور چونے میں سے ایک چیز کو اسی کی مثل چیز اور دوسری اشیاء میں سے کسی چیز کے کچھ اضافے سمیت ادھار (خریدنا یا فروخت کرنا بھی) سود ہے۔","ایک کنکری کے بدلے دو کنکریاں بیچنا بھی سود ہے اور ایک کنکری کے عوض ایک کنکری اور کچھ چونا بیچنا بھی سود ہے، الغرض ہر وہ چیز جو نہ طعام ہو اور نہ ثمن (نقدی، سونا وچاندی وغیرہ) ہو تو اس کی ہم جنس چیز کے ساتھ بیع کرتے وقت کمی بیشی تو جائز ہے لیکن ادھار ناجائز ہے۔"],"472":["§خلاصۃ الباب","اس باب میں تین روایات ہیں، ایک مرفوع (حدیث نبوی)، ایک موقوف (اثر صحابی) اور ایک مقطوع (اثر تابعی) ہے اور مرفوع روایت سنداً صحیح جبکہ باقی دونوں ضعیف ہیں، نیز امام مالک رحمہ اللہ کے تین فتاویٰ بھی مذکور ہیں۔","ایک بیع میں دو بیع کرنے کی مختلف صورتیں ہیں، مثلاً: (۱) آدمی کہے کہ میں تمھیں اپنی فلاں چیز بیچتا ہوں اس شرط پر کہ تم مجھے اپنی فلاں چیز بیچو۔ (۲) یہ چیز نقد لو گے تو سو روپے میں ملے گی اور ادھار لو گے تو ایک سو بیس روپے میں ملے گی اور پھر ان میں سے کسی ایک کو طے کیے بغیر علیحدہ ہو جانا۔ (۳) بیع سلف میں اس لیے پیشگی قیمت دے دی تاکہ مہینے بعد اس کے عوض ایک من گندم وصول کی جائے، لیکن مہینے کے بعد بائع کہے کہ تم مجھے وہی گندم دو ماہ تک بیچ دو، تو گویا پہلی بیع کے اوپر ایک اور بیع کر لی گئی، یہ آخری مثال ایک بیع میں دو بیع کی صورت بھی ہے اور ادھار کے بدلے ادھار بھی ہے۔","نقد، ادھار کا فرق:","نقد ادھار کے فرق میں کچھ صورتیں متفقہ طور پر حرام ہیں اور ایک صورت مختلف فیہ ہے، متفقہ صورتیں یہ ہیں: (۱) بائع نے مشتری کو ایک ہی چیز کی نقد قیمت الگ بتائی اور ادھار قیمت الگ بتائی، پھر وہ ان میں سے کسی ایک کو طے کیے بغیر جدا ہو جائیں، تو یہ بیع حرام ہے خواہ بعد میں مشتری کسی ایک قیمت کو منتخب کر لے (۲) قسطوں کا معاملہ جن میں یہ طے ہوتا ہے کہ ہر ماہ اتنی قسط ادا کرتے رہو، اگر ادا نہ کر سکے تو اتنا اضافہ بھی دینا پڑے گا، یہ صورت بالاتفاق سود ہے اور ایسا سودا کرنا ہی حرام ہے، خواہ آدمی کسی بھی قسط کی ادائیگی میں تاخیر نہ کرے، نیز قسط کی وقت پر ادائیگی نہ کرنے پر کسی بھی قسم کی چھٹی اسی سود میں داخل ہے، خواہ آج کل کے حیلہ ساز، سود خور اسلامی بینکاری کے نام پر یہ کہیں کہ قسط میں تاخیر کی صورت میں ہم تم سے کچھ بھی نہیں لیں گے بلکہ فلاں رفاہی ادارے میں اتنی رقم جمع کرا دینا۔ یہ محض ایک حیلہ ہے اور وہ ادارے بھی دراصل انھی بینکوں سے متعلقہ ہوتے ہیں۔ وہ صورت جس کے متعلق اختلاف ہے، یہ ہے کہ ادھار اور نقد کی قیمتوں میں سے اگر کسی ایک کو منتخب کر کے سودا طے کیا جائے اور پھر جدا ہوا جائے، معاملہ گومگو میں نہ رہے، نیز اگر قیمت کی ادائیگی میں مزید تاخیر ہو تو اس طے شدہ رقم میں کوئی اور اضافہ نہ ہو تو اس کے متعلق علماء وفقہاء کا اختلاف ہے۔ شوافع، حنابلہ اور اکثر اہل حدیث علماء ومفتیان اس کے جواز کے قائل ہیں جبکہ احناف، موالک اور بعض اہل حدیث علماء اسے حرام سمجھتے ہیں، وہ کہتے ہیں کہ یہ وقت کی بیع ہے اور سود ہی کے مشابہ ہے اور ان کی دلیل بعض روایات میں آنے والے یہ الفاظ ہیں: «فَلَهُ أَوْكَسُهُمَا أَوِ الرِّبَا» ’’ان دونوں (قیمتوں) میں سے جو کم تر ہے وہی اس کے لیے (متعین) ہے یا پھر یہ سود ہے۔‘‘ (ترمذی: ۱۲۳۱، ابوداود: ۳۴۶۱، نسائی: ۴۲۳۲، احمد: ۴۳۲/۲، دارمی: ۳۱۹/۱، علامہ البانی نے اسے حسن کہا ہے، ارواء الغلیل: ۱۴۹/۵)...... جواز کے قائلین کے ہاں (۱) یہ روایت ضعیف اور شاذ ہے کیونکہ اس کی سند میں یحییٰ بن زکریا ان الفاظ کو بیان کرنے میں متفرد ہے اور دوسرے ثقات راویوں کی مخالفت کر رہا ہے جنھوں نے یہ الفاظ بیان نہیں کیے، نیز اس کا شیخ محمد بن عمرو متکلم فیہ راوی ہے، لہذا یہ الفاظ حجت ثابت نہ ہوئے۔ (۲) اسے سود کے مشابہ اس لیے نہیں کہہ سکتے کہ سود میں صرف ایک بار اضافہ نہیں ہوتا بلکہ بار بار اور مسلسل اضافہ ہوتا چلا جاتا ہے۔ (۳) یہ ادھار کی وجہ سے طے شدہ اضافہ وقت کی بیع نہیں ہے بلکہ اس چیز کے منافع کی بیع ہے، مثال کے طور پر بائع نے بھینس کی قیمت نقد ایک لاکھ اور سال بعد ادائیگی کی صورت میں سوالاکھ مقرر کی (جس میں مزید تاخیر ہو جائے تو اضافہ نہیں ہونا تھا)، تو اس کا سبب یہ ہے کہ سال بھر میں اس جانور کے دودھ، مکھن وغیرہ کے فوائد بائع کی بجائے مشتری کے پاس چلے گئے اور پھر عموماً سال بعد اشیاء کی چیزوں میں اضافہ بھی تو ہوتا ہی رہتا ہے۔ (۴) یہ مختلف قیمتیں سامنے آنا اور ان میں سے ایک پر راضی ہو کر اس کو پکا کر لینا بالکل اسی طرح ہے کہ جیسے مارکیٹوں، منڈیوں اور بازاروں میں اکثر خریدار دکاندار سے بھاؤ طے کرتے وقت مختلف قیمتیں ذکر کرتا رہتا ہے، اگر بائع ہزار روپے قیمت بتائے تو خریدار پانچ سو سے بات شروع کرتا ہے، پھر دونوں مسلسل بڑھانے گھٹانے میں لگے رہتے ہیں اور بالآخر کسی ایک قیمت پر اتفاق ہو جاتا ہے اور آج تک کسی بھی عالم، فقیہ، معاشرے اور قانون نے اسے ’ایک بیع میں دو بیع‘ یا ’وقت کی بیع‘ شمار نہیں کیا…… بہر حال میرے نزدیک بھی یہی راجح ہے کہ نقد ادھار کی مختلف قیمتوں میں سے اگر ایک کو طے کر لیا جائے کہ جس میں تاخیر کی صورت میں کسی قسم کی مزید چھٹی اور اضافہ نہ پڑتا ہو تو وہ ایک بیع میں دو بیع رہتی ہی نہیں۔ لہٰذا یہ جائز ہے اور فرمان الٰہی ہے:","﴿ إِلَّا أَن تَكُونَ تِجَارَةً عَن تَرَاضٍ مِّنكُمْ ﴾ [النساء: ۲۹]","’مگر یہ کہ آپس کی رضامندی سے تجارت ہو۔‘ پھر بھی اگر کسی شخص کا دل اس پر مطمئن نہ ہو رہا ہو اور وہ کئی ایک علماء وفقہاء کی جانب سے اس معاملے پر سود اور حرمت کے فتوے سن کر شک وشبہ میں مبتلا ہو تو ایسے افراد کے لیے یہ فرمان نبوی صلی اللہ علیہ وسلم مشعل راہ ہے: «فَمَنِ اتَّقَى الشُّبُهَاتِ اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ وَمَنْ وَقَعَ فِي الشُّبُهَاتِ وَقَعَ فِي الْحَرَامِ» ’پھر جو شخص شبہات سے بچ جائے تو اس نے اپنے دین اور عزت کو بچا لیا اور جو کوئی شبہات میں داخل ہو جائے وہ حرام میں بھی داخل ہو جائے گا۔‘ (بخاری: ۵۲، مسلم: ۱۵۹۹، واللفظ لمسلم)","نقد ادھار کی مذکورہ مختلف فیہ صورت پر صرف وہ شخص عمل کرے جسے خود دلائل سمجھ میں آ جائیں جو کہ آسان ہی ہیں یا پھر اسے کسی شیخ واستاد کے تقویٰ وعلم اور دیانت وتحقیق پر اعتماد ہو اور وہ شیخ اس کے جواز کا قائل ہو، لیکن یہ یاد رہے کہ جن لوگوں کی تحقیق میں یہ صورت مشکوک یا ممنوع ہے ان کے لیے یہ قطعاً مناسب نہیں کہ وہ جواز کے قائلین پر سودخوری اور اللہ سے جنگ کا فتویٰ لگائیں، ہر کوئی اپنی تحقیق کا پابند ہے اور اگر اخلاص سے تحقیق کرتا ہے تو خواہ درستگی نہ بھی پا سکے اس کے لیے اللہ کے ہاں ایک اجر ضرور لکھا جاتا ہے، رسول اللہ صلی اللہ علیہ وسلم کا فرمان مبارک ہے: «إِذَا حَكَمَ الْحَاكِمُ فَاجْتَهَدَ ثُمَّ أَصَابَ فَلَهُ أَجْرَانِ وَإِذَا حَكَمَ فَاجْتَهَدَ ثُمَّ أَخْطَأَ فَلَهُ أَجْرٌ» ’جب حاکم فیصلہ کرے اور اجتہاد کرے پھر درستگی کو پہنچ جائے تو اس کے لیے دو اجر ہیں اور جب وہ فیصلہ کرے اور اجتہاد کرے پھر خطا کر بیٹھے تو بھی اس کے لیے ایک اجر ہے۔‘ (صحیح بخاری: ۷۳۵۲)"],"473":["§خلاصۃ الباب","اس باب میں ایک مرفوع روایت (حدیث نبوی) ہے جو بخاری ومسلم میں بھی موجود ہے، نیز امام مالک رحمہ اللہ کے آٹھ فتاویٰ جات بھی مذکور ہیں۔"],"474":["§خلاصۃ الباب","اس باب میں صرف ایک حدیث نبوی ہے جو بخاری ومسلم میں بھی موجود ہے، نیز امام مالک رحمہ اللہ کے تین فتاویٰ بھی مذکور ہیں۔"],"475":["§خلاصۃ الباب","اس باب میں کوئی روایت نہیں ہے، البتہ امام مالک رحمہ اللہ کے پانچ فتاویٰ جات مذکور ہیں۔","بعض لوگ اپنے مال کے متعلق دوسروں کو یہ بتا دیتے ہیں کہ اس کی اصل قیمت اور لاگت اتنی ہے اور ہم اسے اتنے فی صد نفع پر بیچیں گے، تو یہ مال اصلی پر مقررہ اضافہ کے ساتھ بیع کرنا، بیع ’’مرابحہ‘‘ کہلاتا ہے۔ چنانچہ اگر بعد میں کوئی ایسی صورت سامنے آ جائے کہ جس سے معلوم ہو کہ بائع مقرر اور طے شدہ نفع سے زائد وصول کر رہا ہے، خواہ دھوکا دے کر یا کسی کرنسی کا ریٹ گھٹنے بڑھنے کی صورت میں، تو گویا وہ بیع مرابحہ والی بات پر قائم نہ رہا۔","حَدَّثَنِي يَحْيَى، قَالَ مَالِكٌ: الْأَمْرُ الْمُجْتَمَعُ عَلَيْهِ عِنْدَنَا فِي الْبَزِّ يَشْتَرِيهِ الرَّجُلُ بِبَلَدٍ، ثُمَّ يَقْدَمُ بِهِ بَلَدًا آخَرَ فَيَبِيعُهُ مُرَابَحَةً: إِنَّهُ لَا يَحْسِبُ فِيهِ أَجْرَ السَّمَاسِرَةِ، وَلَا أَجْرَ الطَّيِّ، وَلَا الشَّدِّ، وَلَا النَّفَقَةَ، وَلَا كِرَاءَ بَيْتٍ، فَأَمَّا كِرَاءُ الْبَزِّ فِي حُمْلَانِهِ، فَإِنَّهُ يُحْسَبُ فِي أَصْلِ الثَّمَنِ، وَلَا يُحْسَبُ فِيهِ رِبْحٌ، إِلَّا أَنْ يُعْلِمَ الْبَائِعُ مَنْ يُسَاوِمُهُ بِذَلِكَ كُلِّهِ، فَإِنْ رَبَّحُوهُ عَلَى ذَلِكَ كُلِّهِ بَعْدَ الْعِلْمِ بِهِ فَلَا بَأْسَ بِهِ.","امام مالک رحمہ اللہ نے فرمایا: ہمارے ہاں اس حکم پر اتفاق ہے اس کپڑے کے متعلق جسے آدمی کسی شہر سے خریدتا ہے، پھر وہ اسے لے کر کسی دوسرے شہر میں آ جاتا ہے اور اسے ’’مرابحہ‘‘ کے طور پر بیچتا ہے، تو بلاشبہ اس (کپڑے کی اصل لاگت) میں وہ نہ تو دلالوں کی اجرت شمار کرے گا، نہ کپڑا تہہ کرنے کی اجرت، نہ اسے باندھنے کی مزدوری، نہ (اپنے کھانے پینے وغیرہ کا) خرچ، اور نہ مکان کا کرایہ رہا کپڑے کا بوجھ اٹھوانے (بار برداری) کا کرایہ تو وہ اصل لاگت میں تو شمار ہوگا لیکن نفع میں شمار نہ ہوگا، الا یہ کہ بائع جن لوگوں سے بھاؤ طے کرے گا ان کو ان سب چیزوں کے متعلق بتا دے، پھر وہ یہ معلوم کر لینے کے بعد اسے ان سب پر نفع دے دیں تو اس میں کوئی حرج نہیں ہے۔","دراصل اگر ان تمام چیزوں میں صرف ہونے والی مزدوریوں کو اصل لاگت میں شامل کریں تو وہ کافی بڑھ جائے گی، پھر ’’بیع مرابحہ‘‘ کے طور پر جو نفع مقرر کیا ہوگا وہ بھی کافی بڑھ جائے گا، الا یہ کہ گاہک اس پر راضی ہوں تو الگ بات ہے۔ اصل لاگت میں بار برداری کا خرچ شامل کرنے لیکن نفع میں شامل نہ کرنے کی مثال یہ ہے کہ چیز کی اصل لاگت ۱۲۰۰ روپے ہو تو چوتھا حصہ نفع مقرر ہونے کی صورت میں تین سو روپے بنے گا اور چیز کی قیمت (۳۰۰ + ۱۲۰۰ =) ۱۵۰۰ روپے بنے گی اور بار برداری پر دو سو روپے خرچ آیا ہو تو وہ اب غیر نفع کے ساتھ ملائے جائیں گے اور کل قیمت فروخت (۱۵۰۰ + ۲۰۰) ۱۷۰۰ روپے بن جائے گی۔ یہ نہیں ہوگا کہ ۲۰۰ روپے پر بھی چوتھا حصہ یعنی ۵۰ روپے نفع وصول کرتے ہوئے قیمت فروخت ۱۷۵۰ روپے بنائیں، الا یہ کہ خریدار راضی ہو تو جائز ہے۔","قَالَ مَالِكٌ: فَأَمَّا الْقِصَارَةُ وَالْخِيَاطَةُ وَالصِّبَاغُ، وَمَا أَشْبَهَ ذَلِكَ، فَهُوَ بِمَنْزِلَةِ الْبَزِّ، يُحْسَبُ فِيهِ الرِّبْحُ كَمَا يُحْسَبُ فِي الْبَزِّ، فَإِنْ بَاعَ الْبَزَّ وَلَمْ يُبَيِّنْ شَيْئًا مِمَّا سَمَّيْتُ، إِنَّهُ لَا يُحْسَبُ لَهُ فِيهِ رِبْحٌ، فَإِنْ فَاتَ الْبَزُّ، فَإِنَّ الْكِرَاءَ يُحْسَبُ وَلَا يُحْسَبُ عَلَيْهِ رِبْحٌ، فَإِنْ لَمْ يَفُتِ الْبَزُّ، فَالْبَيْعُ مَفْسُوخٌ بَيْنَهُمَا، إِلَّا أَنْ يَتَرَاضَيَا عَلَى شَيْءٍ مِمَّا يَجُوزُ بَيْنَهُمَا.","امام مالک رحمہ اللہ نے فرمایا: رہی کپڑوں کی دھلائی اور سلائی اور رنگائی اور ان جیسی دوسری چیزیں تو وہ (ہر عمل) کپڑے ہی کی طرح ہے (اور کپڑے کی لاگت میں شامل ہے) اس میں بھی نفع اسی طرح شمار کیا جائے گا جس طرح کہ کپڑے میں شمار کیا جاتا ہے، پھر اگر اس نے کپڑا بیچ دیا اور ان چیزوں میں سے کوئی بھی چیز بیان نہ کی جن کا میں نے نام لیا ہے (اور میں نے جن کا تھوڑی دیر پہلے ذکر کیا ہے) کہ ان میں نفع شمار نہیں کیا جاتا (یعنی دلالی، بندھوائی وغیرہ کی اجرت اور پھر تنازعہ کھڑا ہو جائے کہ اصل لاگت تو کم تھی اور نفع زیادہ بٹورا گیا ہے تو امام مالک رحمہ اللہ نے فرمایا:) چنانچہ اگر کپڑا فوت ہو چکا ہو (خریدنے والے نے اسے آگے بیچ دیا ہو یا استعمال کر لیا ہو) تو بلاشبہ (صرف بار برداری کا) کرایہ شمار ہوگا، البتہ اس پر نفع نہیں لیا جائے گا (یہ سارا حساب کر کے دیکھا جائے گا کہ اگر بائع نے واقعی زیادہ رقم بٹوری تھی تو وہ زائد مقدار اس سے واپس کرائی جائے گی) اور اگر کپڑا ہاتھ سے نہ نکلا ہو تو ان دونوں (بائع ومشتری) کے درمیان بیع منسوخ ہو جائے گی، الا یہ کہ وہ کسی ایسی چیز پر باہم رضامند ہو جائیں جو ان کے مابین جائز ہو۔","قَالَ مَالِكٌ فِي الرَّجُلِ يَشْتَرِي الْمَتَاعَ بِالذَّهَبِ أَوْ بِالْوَرِقِ، وَالصَّرْفُ يَوْمَ اشْتَرَاهُ عَشَرَةُ دَرَاهِمَ بِدِينَارٍ، فَيَقْدَمُ بِهِ بَلَدًا فَيَبِيعُهُ","امام مالک رحمہ اللہ نے اس شخص کے متعلق فرمایا جو سونے یا چاندی کے عوض سامان خریدتا ہے اور جس دن اس نے اسے خریدا اس دن سونے اور چاندی کی باہمی تبدیلی اور مُرَابَحَةً، أَوْ يَبِيعُهُ حَيْثُ اشْتَرَاهُ مُرَابَحَةً عَلَى صَرْفِ ذَلِكَ الْيَوْمِ الَّذِي بَاعَهُ فِيهِ، فَإِنَّهُ إِنْ كَانَ ابْتَاعَهُ بِدَرَاهِمَ وَبَاعَهُ بِدَنَانِيرَ، أَوِ ابْتَاعَهُ بِدَنَانِيرَ وَبَاعَهُ بِدَرَاهِمَ، وَكَانَ الْمَتَاعُ لَمْ يَفُتْ فَالْمُبْتَاعُ بِالْخِيَارِ، إِنْ شَاءَ أَخَذَهُ، وَإِنْ شَاءَ تَرَكَهُ، فَإِنْ فَاتَ الْمَتَاعُ كَانَ لِلْمُشْتَرِي بِالثَّمَنِ الَّذِي ابْتَاعَهُ بِهِ الْبَائِعُ، وَيُحْسَبُ لِلْبَائِعِ الرِّبْحُ عَلَى مَا اشْتَرَاهُ بِهِ عَلَى مَا رَبَّحَهُ الْمُبْتَاعُ.","کرنسی چینج کرانے کا بھاؤ ’’ایک دینار کے عوض دس درہم‘‘ تھا، پھر وہ اسے لے کر کسی اور شہر میں آ جاتا ہے اور اسے مرابحہ کے طور پر بیچتا ہے یا جہاں اسے خریدا تھا وہیں بطور مرابحہ بیچتا ہے اور جس دن میں اسے بیچتا ہے اس دن کے کرنسی کے بھاؤ کے حساب پر فروخت کرتا ہے (مثلاً دس فیصد نفع طے کیا، کپڑے کو دس دینار یعنی سونے کے سکوں میں خریدا تھا تو اب گیارہ دینار میں بیچ دیا یا سو درہم یعنی چاندی کے سکوں میں خریدا تھا اور ایک سو دس درہم میں بیچا تھا تو اس میں کوئی حرج نہیں، اگر کوئی تنازعہ کھڑا ہو تو یہ بیچ درست ہی شمار ہوگی، خواہ سونے چاندی کے ریٹ میں کمی بیشی ہو چکی ہو، کیونکہ اس نے سونے کے بدلے خود خریداری کی تھی اور سونے کے عوض ہی مال بیچا ہے یا چاندی کے بدلے خرید کر چاندی ہی کے عوض اسے بیچ دیا، چنانچہ فیصلہ بائع کے حق میں ہوگا اور بیع منسوخ نہ ہوگی، نہ بائع پر کوئی چھٹی پڑے گی، لیکن اگر سونے کے بدلے خریداری کر کے مال کو چاندی کے عوض بیچے یا اس کے الٹ کرے اور خریداری کے دن والے اور فروخت کے دن والے کرنسی ریٹ میں فرق ہو اور پھر تنازعہ کھڑا ہو جائے) تو اگر اس نے خریدا تو درہموں کے عوض تھا اور بیچا دیناروں کے عوض ہو یا دیناروں کے بدلے خریدا ہو اور درہموں کے عوض بیچ دیا ہو اور سامان (جوں کا توں موجود ہو،) فوت نہ ہوا ہو تو (اس سے) خریدنے والے کو اختیار ہوگا، اگر چاہے تو اسے لیے رکھے اور اگر چاہے تو اسے چھوڑ دے (اور سودا واپس کر کے اپنی رقم لے لے، اور یہ اختیار اس لیے ہے کہ اس نے جو نفع لینا تھا وہ اپنی قیمت خرید پر لینا تھا جو مثال کے طور پر اس نے سونے کی شکل میں ادا کی تھی لیکن اس نے بیچتے وقت سونے کی شکل میں نفع نہیں لیا بلکہ چاندی کی صورت میں حاصل کیا ہے، حالانکہ دونوں کے استعمال اور ریٹ میں فرق ہے، پھر کبھی سونا چڑھ جاتا ہے اور کبھی چاندی مہنگی ہو جاتی ہے۔ الغرض بائع اپنی بات پر پکا نہیں رہا اور اگر سامان فوت ہو چکا ہو تو وہ اس مشتری کے لیے اسی قیمت کے عوض ہوگا جس کے عوض بائع نے اسے خریدا تھا اور (اب بائع کا مقرر کردہ نفع نا قابل اعتبار ہوگا بلکہ) اس نے جس قیمت پر اسے خریدا تھا اس پر وہ اسی حساب سے نفع شمار کرے گا جو اس کا خریدار اسے دینے پر راضی ہو۔ (خواہ تھوڑا ہو یا زیادہ اور اس سے زائد رقم بائع سے واپس لے لی جائے گی)۔","قَالَ مَالِكٌ: إِذَا بَاعَ رَجُلٌ سِلْعَةً قَامَتْ عَلَيْهِ بِمِئَةِ دِينَارٍ، لِلْعَشَرَةِ أَحَدَ عَشَرَ، ثُمَّ جَاءَهُ","امام مالک رحمہ اللہ نے فرمایا: اور جب کوئی آدمی کسی ایسے سامان کو فروخت کرے جو اسے سو دینار میں پڑا تھا (اور وہ بَعْدَ ذَلِكَ أَنَّهَا قَامَتْ عَلَيْهِ بِتِسْعِينَ دِينَارًا، وَقَدْ فَاتَتِ السِّلْعَةُ خُيِّرَ الْبَائِعُ، فَإِنْ أَحَبَّ فَلَهُ قِيمَةُ سِلْعَتِهِ يَوْمَ قُبِضَتْ مِنْهُ، إِلَّا أَنْ تَكُونَ الْقِيمَةُ أَكْثَرَ مِنَ الثَّمَنِ الَّذِي وَجَبَ لَهُ بِهِ الْبَيْعُ أَوَّلَ يَوْمٍ، فَلَا يَكُونُ لَهُ أَكْثَرُ مِنْ ذَلِكَ، وَذَلِكَ مِئَةٌ دِينَارٍ وَعَشَرَةُ دَنَانِيرَ، وَإِنْ أَحَبَّ ضُرِبَ لَهُ الرِّبْحُ عَلَى التِّسْعِينَ، إِلَّا أَنْ يَكُونَ الَّذِي بَلَغَتْ سِلْعَتُهُ مِنَ الثَّمَنِ أَقَلَّ مِنَ الْقِيمَةِ، فَيُخَيَّرُ فِي الَّذِي بَلَغَتْ سِلْعَتُهُ، وَفِي رَأْسِ مَالِهِ وَرِبْحِهِ، وَذَلِكَ تِسْعَةٌ وَتِسْعُونَ دِينَارًا.","اسے بیع مرابحہ کے طور پر دس فیصد نفع مقرر کر کے یوں بیچے کہ (ہر دس کے بدلے گیارہ لے گا) چنانچہ اس نے سو دینار اپنی قیمت خرید بتا کر ایک سو دس وصول کر لیے) پھر اس کے بعد خبر آئی کہ وہ سامان اسے نوے دینار میں پڑا تھا، (اس اعتبار سے وہ اسے ننانوے دینار میں چیز بیچنے کا مجاز ہے لیکن وہ تو ایک سو دس میں بیچ چکا ہے) اور سامان بھی فوت ہو چکا ہے، (اگر موجود ہوتا تو بیع منسوخ کر کے بھاؤ نئے سرے سے طے کر لیتے، لیکن اب تو وہ سامان آگے بک چکا ہے یا استعمال ہو چکا ہے) تو بائع کو اختیار دیا جائے گا کہ اگر وہ پسند کرے تو اسے اس کے سامان کی قیمت اس دن والی مل جائے، جس میں اس سے وصول کیا گیا تھا (اس دن بازار میں اس کی قیمت کا جو ریٹ تھا وہ وصول کر لے اور باقی ماندہ رقم واپس لوٹا دے)، الا یہ کہ (بازار والی) قیمت اس طے شدہ قیمت سے زیادہ ہو جس پر پہلے دن اس کے لیے بیع واجب ہوگئی تھی (یعنی جو قیمت وہ پہلے طے کر کے بیچ چکا تھا) تو اسے اس سے زیادہ نہیں ملیں گے اور وہ ایک سو دس دینار ہیں (یعنی جس دن اس نے اپنی نوے دینار والی چیز سو دینار کی سمجھ کر دس فیصد نفع پر ایک سو دس دینار میں بیچی تھی اس دن بازار میں اس چیز کی قیمت ایک سو پندرہ دینار تھی تو اب مذکورہ بالا تنازعہ میں اسے ایک سو دس سے زائد کچھ نہیں ملے گا) اور اگر وہ بائع پسند کرے تو اس کے لیے نوے دینار پر نفع کا حساب کر دیا جائے گا (اور نوے پر دس فیصد نفع کے حساب سے ننانوے دینار اس کے لیے ہو جائیں گے اور اس سے زائد جتنی مقدار وہ لے چکا ہو اسے واپس لوٹا دے الا یہ کہ اس کا سامان جس طے شدہ قیمت (ننانوے دینار) کو پہنچنا ہے وہ (بازار کی قیمت سے کم ہو (یعنی فروخت والے دن بازار میں اس چیز کا ریٹ ننانوے دینار سے زیادہ مثلاً ایک سو پانچ ہو) تو اسے اختیار دیا جائے گا کہ یا تو وہ قیمت لے لے جس تک اس کا سامان (بازار کے مطابق) پہنچ چکا ہو (یعنی ایک سو پانچ دینار) یا اپنی کل لاگت اور اس کا نفع لے لے اور وہ ننانوے دینار بنتے ہیں۔","یعنی اس ایک سو دس دینار میں بیچی ہوئی چیز کے متعلق تنازعے کا جب حل ہوگا تو خریدار کو بازار کے ریٹ کے حساب سے مطمئن ہونا پڑے گا، البتہ اگر وہ چیز بازار میں ایک سو دس سے بھی مہنگی تھی تو خریدار پر مزید چھٹی نہ پڑے گی، رہا بائع، تو اسے اختیار ہے کہ چاہے تو بازار کے ریٹ کا حساب لگا لے لیکن ایک سو دس سے اوپر نہ جائے اور چاہے تو طے شدہ بھاؤ کے مطابق نوے دینار والی چیز کے ننانوے دینار لے لے۔ الغرض اس چیز کی قیمت ننانوے سے ایک سو دس کے درمیان درمیان ہی شمار ہوگی، نہ اس سے کم اور نہ اس سے زیادہ، بازار کا ریٹ کم ہوا تو ننانوے سے نیچے نہ جائیں گے اور ایک سو دس سے زیادہ ہوا تو ایک سو دس پر رک جائیں گے۔","قَالَ مَالِكٌ: وَإِنْ بَاعَ رَجُلٌ سِلْعَةً مُرَابَحَةً فَقَالَ: قَامَتْ عَلَيَّ بِمِئَةِ دِينَارٍ، ثُمَّ جَاءَهُ بَعْدَ ذَلِكَ أَنَّهَا قَامَتْ بِمِئَةٍ وَعِشْرِينَ دِينَارًا، خُيِّرَ الْمُبْتَاعُ، فَإِنْ شَاءَ أَعْطَى الْبَائِعَ قِيمَةَ السِّلْعَةِ يَوْمَ قَبَضَهَا، وَإِنْ شَاءَ أَعْطَى الثَّمَنَ الَّذِي ابْتَاعَ بِهِ عَلَى حِسَابِ مَا رَبَّحَهُ، بَالِغًا مَا بَلَغَ، إِلَّا أَنْ يَكُونَ ذَلِكَ أَقَلَّ مِنَ الثَّمَنِ الَّذِي ابْتَاعَ بِهِ السِّلْعَةَ، فَلَيْسَ لَهُ أَنْ يُنْقِصَ رَبَّ السِّلْعَةِ مِنَ الثَّمَنِ الَّذِي ابْتَاعَهَا بِهِ، لِأَنَّهُ قَدْ كَانَ رَضِيَ بِذَلِكَ، وَإِنَّمَا جَاءَ رَبُّ السِّلْعَةِ يَطْلُبُ الْفَضْلَ، فَلَيْسَ لِلْمُبْتَاعِ فِي هَذَا حُجَّةٌ عَلَى الْبَائِعِ بِأَنْ يَضَعَ مِنَ الثَّمَنِ الَّذِي ابْتَاعَ بِهِ عَلَى الْبَرْنَامِجِ.","امام مالک رحمہ اللہ نے فرمایا: اور اگر کسی شخص نے کوئی سامان مرابحہ کے طور پر فروخت کیا اور کہا کہ مجھے سو دینار میں پڑا ہے، پھر بعد میں یہ خبر آئی کہ وہ ایک سو بیس دینار میں پڑا ہے تو اب خریدار کو اختیار دیا جائے گا کہ اگر چاہے تو بائع کو اس سامان کی اس دن والی قیمت ادا کرے جس میں اس نے اسے قبضے میں لیا تھا اور اگر وہ چاہے تو وہ قیمت ادا کرے جس کے عوض اس نے خرید کیا تھا، اس حساب کے مطابق جو اس نے نفع کے لیے طے کیا ہو خواہ وہ جہاں تک بھی پہنچ جائے (مثلاً دس فیصد کا حساب ہو تو سو پر ایک سو دس ادا کیے تھے، اب ایک سو بیس پر دس فیصد نفع یعنی بارہ دینار بڑھا کر ایک سو بتیس دینار لازم ہوں گے، لہذا وہ بائیس دینار مزید ادا کرے) الا یہ کہ (اس دن اس چیز کی) بازار والی قیمت اس طے شدہ قیمت (یعنی ایک سو دس دینار) سے بھی کم ہو جس کے عوض اس (خریدار) نے اسے خرید کیا تھا (مثلاً بازار کا ریٹ ایک سو پانچ دینار ہو) تو اس کے لیے جائز نہیں کہ سامان کے مالک (بائع) کو اس قیمت سے کم ادا کرے جس کے عوض اس نے سامان خریدا تھا، کیونکہ بلاشبہ وہ مشتری اس (ایک سو دس) پر تو راضی ہو چکا تھا اور بلاشبہ سامان کا مالک یعنی بائع تو (ایک سو دس سے بھی) کچھ زائد (دینار) طلب کرتا ہوا آیا ہے، لہذا خریدار کے لیے اس (بازار کے ایک سو پانچ والا کم ریٹ) میں بائع کے خلاف کوئی حجت نہ ہوگی کہ وہ اسے اس قیمت میں بھی کمی کرے جس پر اس نے رسید کے مطابق خریدا تھا۔"],"476":["§خلاصۃ الباب","اس باب میں کوئی روایت نہیں ہے، البتہ امام مالک رحمہ اللہ کے تین فتاویٰ مذکور ہیں۔","برنامج سے مراد وہ کاغذ اور پرچی ہے جس پر کسی سیل بند قسم کے مال کی تفصیل لکھی ہوتی ہے، مزید تفصیل کے لیے پیچھے باب: ۳۵ کا آخری فائدہ دیکھیے۔","قَالَ مَالِكٌ: الْأَمْرُ عِنْدَنَا فِي الْقَوْمِ يَشْتَرُونَ السِّلْعَةَ الْبَزَّ أَوِ الرَّقِيقَ، فَيَسْمَعُ بِهِ الرَّجُلُ فَيَقُولُ لِرَجُلٍ مِنْهُمُ: الْبَزُّ الَّذِي اشْتَرَيْتَ مِنْ فُلَانٍ قَدْ بَلَغَتْنِي صِفَتُهُ وَأَمْرُهُ، فَهَلْ لَكَ أَنْ أُرْبِحَكَ فِي نَصِيبِكَ كَذَا وَكَذَا، فَيَقُولُ: نَعَمْ، فَيُرْبِحُهُ وَيَكُونُ شَرِيكًا لِلْقَوْمِ مَكَانَهُ، فَإِذَا نَظَرَ إِلَيْهِ رَآهُ قَبِيحًا وَاسْتَغْلَاهُ. قَالَ مَالِكٌ: ذَلِكَ لَازِمٌ لَهُ وَلَا خِيَارَ لَهُ فِيهِ، إِذَا كَانَ ابْتَاعَهُ عَلَى بَرْنَامِجٍ وَصِفَةٍ مَعْلُومَةٍ.","امام مالک رحمہ اللہ نے فرمایا: ہمارے ہاں حکم یہ ہے ان (اکٹھے) لوگوں کے متعلق جو کوئی سامان خریدیں، (مثلاً) کپڑا یا غلام، کوئی آدمی اس کے متعلق سن لے تو وہ ان لوگوں میں سے کسی شخص سے کہے کہ تم نے فلاں شخص سے جو کپڑا خریدا ہے، مجھے اس کی صفات اور صورتحال کی خبر پہنچ چکی ہے، تو کیا تمھیں اس بات میں کوئی رغبت ہے کہ میں تمھیں تمھارے حصے میں اس کا اتنا اتنا نفع ادا کروں (اور تیرا حصہ خرید لوں)، وہ کہے کہ ٹھیک ہے، چنانچہ وہ اسے وہ نفع دے دیتا ہے اور اس کی جگہ خود ان لوگوں کا شریک بن جاتا ہے، پھر جب وہ اس سامان کو دیکھتا ہے تو اسے برا اور مہنگا خیال کرتا ہے، (تو اس کے متعلق) امام مالک رحمہ اللہ نے فرمایا: یہ بیچ اس (خریدار) پر لازم ہو جائے گی اور اسے اس (مال کے واپس لوٹانے) میں کوئی اختیار نہ ہوگا، اگر اس نے اسے کاغذ پر اور معلوم وصف پر خریدا ہو۔","قَالَ مَالِكٌ فِي الرَّجُلِ يَقْدَمُ لَهُ أَصْنَافٌ مِنَ الْبَزِّ، وَيَحْضُرُهُ السُّوَّامُ، وَيَقْرَأُ عَلَيْهِمْ بَرْنَامِجَهُ وَيَقُولُ: فِي كُلِّ عِدْلٍ كَذَا وَكَذَا مِلْحَفَةً بَصْرِيَّةً، وَكَذَا وَكَذَا رَيْطَةً سَابِرِيَّةً، ذَرْعُهَا كَذَا وَكَذَا، وَيُسَمِّي لَهُمْ أَصْنَافًا مِنَ الْبَزِّ بِأَجْنَاسِهِ وَيَقُولُ: اشْتَرُوا مِنِّي عَلَى هَذِهِ الصِّفَةِ. فَيَشْتَرُونَ الْأَعْدَالَ عَلَى مَا وَصَفَ لَهُمْ، ثُمَّ يَفْتَحُونَهَا فَيَسْتَغْلُونَهَا وَيَنْدَمُونَ. قَالَ مَالِكٌ: ذَلِكَ لَازِمٌ لَهُمْ إِذَا كَانَ مُوَافِقًا لِلْبَرْنَامِجِ الَّذِي بَاعَهُمْ عَلَيْهِ.","امام مالک رحمہ اللہ نے اس شخص کے متعلق فرمایا جس کے پاس مختلف قسموں کا کپڑا آتا ہے اور اس کے پاس بھاؤ لگانے والے بھی حاضر ہو جائیں، وہ ان کو اپنے برنامے (مال کی تفصیلات والے کاغذات) پڑھ کر سنائے اور ہر گھڑی کے متعلق کہے کہ اس میں اتنی بصری چادریں ہیں، اس میں اتنے سابوری باریک اور ملائم کپڑے ہیں، ان کا ماپ اتنا اتنا ہے، وہ ان کے سامنے کپڑے کی مختلف اجناس اور اقسام کے نام بھی لے اور کہے کہ مجھ سے اس وصف کے مطابق اسے خرید لو، چنانچہ وہ اس کے بیان کے مطابق اس سے گھڑیاں خرید لیتے ہیں، پھر اسے کھولتے ہیں تو اسے مہنگا محسوس کرتے ہیں اور نادم ہو جاتے ہیں۔ تو امام مالک رحمہ اللہ نے فرمایا: یہ بیچ ان کے لیے لازم ہے (بشرطیکہ) جب وہ سامان اس برنامے اور کاغذ کے مطابق ہو جس پر اس نے انھیں وہ بیچا تھا۔","ریطہ ایک پاٹ کی چادر کو کہتے ہیں یعنی جس میں کوئی جوڑ نہ ہو، نیز ملائم اور باریک کپڑے پر بھی اس کا اطلاق ہوتا ہے۔ سابر یہ عمدہ و باریک کپڑے کو کہتے ہیں، بعض شارحین نے اس سے ایران کے قصبہ ’’سابور‘‘ کی طرف نسبت مراد لی ہے۔","قَالَ مَالِكٌ: وَهَذَا الْأَمْرُ الَّذِي لَمْ يَزَلْ عَلَيْهِ النَّاسُ عِنْدَنَا يُجِيزُونَهُ بَيْنَهُمْ، إِذَا كَانَ الْمَتَاعُ مُوَافِقًا لِلْبَرْنَامِجِ وَلَمْ يَكُنْ مُخَالِفًا لَهُ.","امام مالک رحمہ اللہ نے فرمایا: اور یہی وہ حکم ہے جس پر ہمارے ہاں ہمیشہ سے لوگ قائم عمل کرتے چلے آرہے ہیں، وہ اسے آپس میں جائز قرار دیتے ہیں، جس وقت کہ سامان برنامے کے مطابق ہو اور اس کے مخالف نہ ہو۔","چنانچہ اگر وہ تحریر شدہ تفصیل کے خلاف نکلے تو اگر خریدار چاہے تو بیع فسخ ہو جائے گی۔"],"477":["§خلاصۃ الباب","اس باب میں دو مرفوع روایات (احادیث نبویہ) ہیں جو سنداً صحیح ثابت ہیں، نیز امام مالک رحمہ اللہ کے تین فتاویٰ جات بھی مذکور ہیں۔","چونکہ ہر انسان کو خرید وفروخت سے اکثر واسطہ پڑتا رہتا ہے، اس لیے سہولت کی خاطر مختلف قسم کے اختیارات لوگوں کو عطا کیے گئے ہیں تاکہ تنازعات کا حل بآسانی ہوتا رہے اور لوگ دھوکا، فراڈ اور نقصان سے بچے رہیں، اختیار سے یہاں یہ مراد ہے کہ بیع کو قائم رکھا جائے یا فسخ کر دیا جائے، چنانچہ اس کی مختلف اقسام شریعت سے ثابت ہیں۔ مثلاً: (۱) خیار مجلس، اس کا بیان اس باب کی پہلی روایت میں آ رہا ہے، یعنی بائع اور مشتری جب تک خرید و فروخت والی مجلس میں موجود رہیں اور جدا جدا نہ ہوں تو دونوں کو بیع فسخ کرنے کا اختیار ہوتا ہے۔ (۲) خیار شرط یعنی بیع کے وقت بائع یا مشتری کچھ متعین عرصے کے لیے اختیار حاصل کر لے۔ (۳) خیار رویت یعنی خرید کیا ہوا مال دیکھنے پر بیع کو ختم کرنے یا باقی رکھنے کا اختیار (۴) خیار عیب یعنی حاصل شدہ رقم یا خرید شدہ چیز میں عیب ثابت ہو جانے پر بیع کو فسخ کرنے یا جاری رکھنے کا اختیار۔ (۵) خیار غبن یعنی دھوکا ثابت ہو جانے پر بیع منسوخ کرنے کا اختیار۔"],"478":["§خلاصۃ الباب","اس باب میں تین روایات ہیں، دو موقوف (آثار صحابہ) ہیں جن میں سے ایک صحیح اور ایک سنداً حسن ہے۔ اور ایک مقطوع اثر (تابعی) ہے جس کی سند صحیح ہے، نیز امام مالک رحمہ اللہ کے چار فتاویٰ بھی اس باب میں مذکور ہیں۔"],"479":["§خلاصۃ الباب","اس باب میں دو روایات ہیں، جن میں سے ایک مرفوع (حدیث نبوی) ہے جو صحیح مسلم میں بھی ہے اور دوسری مقطوع (اثر تابعی) ہے اور وہ بھی سند صحیح ہے۔ نیز امام مالک رحمہ اللہ کے پانچ فتاویٰ بھی اس باب میں مذکور ہیں جن میں سے بعض تو بعض کی تفسیر اور وضاحت ہی ہیں۔","’’حول‘‘ کے معنی منتقل ہونے کے ہیں۔ جیسا کہ قرآن مجید میں ہے:","﴿ وَلَا يَبْغُونَ عَنْهَا حِوَلًا ﴾ [الکہف: ۱۰۸]","’’وہ (جنتی) اس (جنت) سے جگہ بدلنا (اور منتقل ہونا) نہ چاہیں گے۔‘‘","اسے اصطلاحاً ’’حوالہ دینا‘‘ کہتے ہیں یعنی کوئی شخص اپنا قرض کسی اور کے ذمے منتقل کر کے اس سے وصول کرنے کا حوالہ دے دیتا ہے، اس کی صورت یہ بنتی ہے کہ ایک شخص کا دوسرے شخص پر قرض ہوتا ہے اور اس دوسرے شخص کا کسی تیسرے شخص کے ذمے قرض ہوتا ہے تو یہ دوسرا شخص اپنے قرض خواہ یعنی پہلے شخص سے کہتا ہے کہ میں نے جو قرض اپنے مقروض یعنی تیسرے شخص سے وصول کرنا ہے وہ تم اس سے لے لو، اس کی طرف سے وہ مجھے واپس مل جائے گا اور میری طرف سے تمھیں مل جائے گا۔"],"480":["§خلاصۃ الباب","اس باب میں کوئی روایت نہیں ہے، البتہ امام مالک رحمہ اللہ کے پانچ فتاویٰ جات مذکور ہیں۔","شرکت اس عقد اور معاملے کو کہتے ہیں جو دو شریکوں کے درمیان اصل مال اور نفع کے متعلق طے پاتا ہے، یہاں بائع کا مشتری کے ساتھ ہی شریک ہو جانا مراد ہے۔ ’’تولیت‘‘ کا لغوی مفہوم یہ ہے کہ اپنی خریدی ہوئی چیز، قیمت خرید ہی میں کسی کی ولایت میں دے دینا۔ یہاں اس سے یہ مراد ہے کہ مشتری خریدی ہوئی چیز کو بائع کے ہاتھ یا کسی اور کے ہاتھ قیمت خرید ہی میں سپرد کر دے، یعنی جتنے میں لے اتنے میں دے اور ’’اقالہ‘‘ فسخ بیع کو کہتے ہیں... دراصل ایک روایت میں ان تینوں کا اکٹھا تذکرہ یوں ہوا ہے: «مَنِ ابْتَاعَ طَعَامًا فَلَا يَبِعْهُ حَتَّى يَقْبِضَهُ إِلَّا أَنْ يُشْرِكَ فِيهِ أَوْ يُوَلِّيَهُ أَوْ يُقِيلَهُ» جس کسی نے طعام خریدا تو وہ اسے قبضے میں لے لینے سے پہلے آگے نہ بیچے، الا یہ کہ اس میں (بائع ہی کے ساتھ) شراکت کر لے یا اسے جتنے میں لے اتنے میں (بائع ہی کو) دے دے یا اس کی بیع فسخ کر دے۔‘‘ (ابوداود بحوالہ زرقانی ۴۰۰/۳، ۴۰۱، یہ روایت مرسل ہے جسے سعید بن مسیب رحمہ اللہ نے مرفوع ذکر کیا ہے، موطا درسی نسخہ: ص ۶۰۸) امام مالک رحمہ اللہ شرکت و تولیت کے قائل ہیں جبکہ امام ابو حنیفہ اور امام شافعی رحمہما اللہ اسے ممنوع کہتے ہیں، رہا اقالہ تو اس کے جواز پر سب متفق ہیں۔ امام مالک رحمہ اللہ کے نزدیک یہ تینوں امور مکارم اخلاق والے عقد ہیں جن میں بائع اور مشتری کو استثنائی سہولیات مہیا کی گئی ہیں جس طرح کہ بیع مزابنہ میں سے بیع عریہ کو مستثنیٰ کیا گیا ہے۔","قَالَ مَالِكٌ فِي الرَّجُلِ يَبِيعُ الْبَزَّ الْمُصَنَّفَ وَيَسْتَثْنِي ثِيَابًا بِرُقُومِهَا: إِنَّهُ إِنِ اشْتَرَطَ أَنْ يَخْتَارَ مِنْ ذَلِكَ الرَّقْمَ فَلَا بَأْسَ بِهِ، وَإِنْ لَمْ يَشْتَرِطْ أَنْ يَخْتَارَ مِنْهُ حِينَ اسْتَثْنَى، فَإِنِّي أَرَاهُ شَرِيكًا فِي عَدَدِ الْبَزِّ الَّذِي اشْتُرِيَ مِنْهُ، وَذَلِكَ أَنَّ الثَّوْبَيْنِ يَكُونُ رَقْمُهُمَا سَوَاءً، وَبَيْنَهُمَا تَفَاوُتٌ فِي الثَّمَنِ.","امام مالک رحمہ اللہ نے اس شخص کے متعلق فرمایا جو کئی قسم کا کپڑا بیچتا ہے اور وہ ان میں سے کچھ کپڑوں کو ان پر لگی ہوئی علامات سمیت مستثنیٰ کر لیتا ہے تو بلاشبہ (اس کی دو صورتیں بنتی ہیں، چنانچہ اگر اس نے یہ شرط لگا لی کہ وہ ان علامتوں کو خود منتخب کرے گا تو اس میں کوئی حرج نہیں ہے اور (لیکن) اگر اس نے جب استثناء کیا تو یہ شرط نہ لگائی کہ وہ اسے منتخب کرے گا تو یقیناً میں یہی سمجھتا ہوں کہ وہ (بائع اپنے خریدار کا) شریک بن جائے گا اس کپڑے میں جو اس سے خریدا گیا ہے (اب نہ تو وہ کچھ خاص کپڑوں کو منتخب کرنے کا اختیار پا سکے گا اور نہ بیع فسخ ہوگی، بلکہ دونوں باہم شریک بن جائیں گے) اور یہ (شرکت) اس لیے ہے کہ بے شک (بعض اوقات) دو کپڑوں کی علامت ایک جیسی ہوتی ہے لیکن ان کی قیمتوں میں کمی بیشی ہوتی ہے۔ اور اس قیمت کے اختلاف کی بنا پر بعد میں جھگڑا ہو سکتا ہے، دونوں مہنگے کپڑے کی خواہش کریں گے۔","’’رقوم‘‘ جمع ہے ’’رقم‘‘ کی جس کے معنی ہیں: ’’نمبر، علامت، نقش ونگار اور چیز پر لگی ہوئی قیمت وغیرہ کی چٹ‘‘۔ بائع نے تیس کپڑے بیچے، دس مستثنیٰ کیے جو کہ بیچے ہوئے مال کا تہائی حصہ ہیں، لیکن بائع نے یہ شرط طے نہ کی کہ جنھیں چاہوں گا منتخب کر لوں گا، تو اس صورت میں بائع اس مشتری کا شریک بن جائے گا، ان تیس کپڑوں کی کل مالیت میں ایک تہائی حصہ بائع کا اور دو تہائی مشتری کا ہوگا۔","قَالَ مَالِكٌ: الْأَمْرُ عِنْدَنَا: أَنَّهُ لَا بَأْسَ بِالشِّرْكِ وَالتَّوْلِيَةِ وَالْإِقَالَةِ مِنْهُ، فِي الطَّعَامِ، وَغَيْرِهِ قَبَضَ ذَلِكَ أَوْ لَمْ يَقْبِضْ، إِذَا كَانَ ذَلِكَ بِالنَّقْدِ وَلَمْ يَكُنْ فِيهِ رِبْحٌ وَلَا وَضِيعَةٌ وَلَا تَأْخِيرٌ لِلثَّمَنِ، فَإِنْ دَخَلَ ذَلِكَ رِبْحٌ أَوْ وَضِيعَةٌ أَوْ تَأْخِيرٌ مِنْ وَاحِدٍ مِنْهُمَا، صَارَ بَيْعًا يُحِلُّهُ مَا يُحِلُّ الْبَيْعَ، وَيُحَرِّمُهُ مَا يُحَرِّمُ الْبَيْعَ، وَلَيْسَ بِشِرْكٍ وَلَا تَوْلِيَةٍ وَلَا إِقَالَةٍ.","امام مالک رحمہ اللہ نے فرمایا: ہمارے ہاں حکم یہ ہے کہ بے شک (اس طرح کی بیع سے) شرکت، تولیت اور اقالہ کرنے میں کوئی حرج نہیں ہے۔ کھانے پینے کی چیزوں میں بھی اور اس کے علاوہ میں بھی (جائز ہے، خواہ) مشتری نے مال قبض کیا ہو یا نہ کیا ہو۔ (بشرطیکہ) یہ سب نقد ہو اور اس عقد میں نہ نفع ہو نہ نقصان اور نہ قیمت ادھار ہو، چنانچہ اگر اس عقد میں بائع اور مشتری میں سے کسی ایک کی جانب سے نفع یا کمی یا تاخیر داخل ہو جائے تو یہ عقد ’’بیع‘‘ ہو جائے گا، اسے وہ چیز حلال کرے گی جو بیع کو حلال قرار دیتی ہے اور وہ چیز اسے حرام کر دے گی جو بیع کو حرام قرار دیتی ہے اور (نفع ونقصان یا ادھار کی صورت میں) یہ نہ تو شراکت ہوگی، نہ تولیت اور نہ ہی اقالہ۔","قَالَ مَالِكٌ: مَنِ اشْتَرَى سِلْعَةً بَزًّا أَوْ رَقِيقًا فَبَتَّ بِهِ، ثُمَّ سَأَلَهُ رَجُلٌ أَنْ يُشَرِّكَهُ فَفَعَلَ وَنَقَدَا الثَّمَنَ صَاحِبَ السِّلْعَةِ جَمِيعًا، ثُمَّ أَدْرَكَ السِّلْعَةَ شَيْءٌ يَنْتَزِعُهَا مِنْ أَيْدِيهِمَا، فَإِنَّ الْمُشَرَّكَ يَأْخُذُ مِنَ الَّذِي أَشْرَكَهُ الثَّمَنَ، وَيَطْلُبُ الَّذِي أَشْرَكَ بَيْعَهُ الَّذِي بَاعَهُ السِّلْعَةَ بِالثَّمَنِ كُلِّهِ، إِلَّا أَنْ يَشْتَرِطَ الْمُشَرِّكُ عَلَى الَّذِي أَشْرَكَهُ بِحَضْرَةِ الْبَيْعِ، وَعِنْدَ مُبَايَعَةِ الْبَائِعِ الْأَوَّلِ وَقَبْلَ أَنْ يَتَفَاوَتَ ذَلِكَ: أَنَّ عُهْدَتَكَ عَلَى الَّذِي ابْتَعْتُ مِنْهُ، وَإِنْ تَفَاوَتَ ذَلِكَ وَفَاتَ الْبَائِعَ الْأَوَّلَ، فَشَرْطُ الْآخَرِ بَاطِلٌ وَعَلَيْهِ الْعُهْدَةُ.","امام مالک رحمہ اللہ نے فرمایا: جس شخص نے کوئی سامان خریدا، کپڑا یا غلام اور اس (کی بیع) کو پختہ اور قطع بنا دیا (کوئی اختیار وغیرہ باقی نہ رہنے دیا)، پھر اس سے کسی شخص نے سوال کیا کہ وہ اسے بھی (اس خریداری میں) شریک کر لے، چنانچہ اس نے ایسا کر لیا اور دونوں نے سامان کے مالک کو اکٹھے ہی نقد قیمت ادا کر دی۔ اب ان تمام افراد اور معاملات کی نوعیت یہ ہوگئی کہ (۱) سامان والا شخص ’’صاحب السلعۃ‘‘ یعنی سامان کا مالک اور پہلا بائع ہے اور (۲) اس کے ساتھ جو شروع میں ایک خریدار نے معاملہ کیا تھا اسے پہلی بیع کہیں گے اور یہ پہلا خریدار ہے اور اس خریدار نے چونکہ کسی کو شریک بھی کیا اور پھر دوبارہ مل کر خریداری کا معاملہ کیا تو گویا اس نے اپنا حصہ دوسرے خریدار کے ہاتھ بیچ دیا، اس لیے اس کے تین نام ہوں گے: پہلا خریدار، دوسرا بائع اور شریک کرنے والا جبکہ دوسرے خریدار کے دو نام ہوں گے، دوسرا خریدار اور مشرک یعنی شریک کیا جانے والا) پھر اس سامان کو کوئی ایسی چیز نے پالیا جس نے اسے ان دونوں کے ہاتھوں سے چھین لیا (یعنی ثابت ہو گیا کہ یہ سامان کسی اور ہی شخص کی ملکیت تھا اور وہ اصل مستحق اسے لے کر چلا گیا تو اب ان دونوں شریک خریداروں کے ہاتھ میں نہ سامان رہا نہ قیمت، اس لیے وہ اب اپنی قیمت واپس لیں گے، لیکن طریق کار یہ ہوگا کہ) بلاشبہ جسے شریک کیا گیا تھا (یعنی دوسرا خریدار) وہ اس شخص سے اپنی قیمت وصول کرے گا جس نے اسے شریک کیا تھا (یعنی پہلے خریدار سے وصول کرے گا) اور جس شخص نے شریک کیا تھا وہ اس بائع سے پوری قیمت کا مطالبہ کرے گا جس نے اسے اپنا سامان بیچا تھا، الا یہ کہ شریک کیے جانے والے (دوسرے خریدار) نے بائع کی موجودگی میں شریک کرنے والے پر یہ شرط کر لی ہو کہ بیشک (کسی خرابی اور فتور کے ثابت ہونے پر چٹی اور ذمہ داری اور جواب دہی اس (بائع اول) پر ہوگی جس سے میں نے (تمھارے ساتھ مل کر مال کی) خریداری کی ہے، اور (یہ شرط) بائع اول کے ساتھ بیع کرتے وقت اور ان سب کے الگ الگ ہونے سے قبل (طے کی گئی) ہو (تو پھر یہ شریک ہونے والا شخص مال چھن جانے کی صورت میں شریک کرنے والے سے اپنی قیمت نہ لے گا بلکہ سامان کے مالک بائع اول ہی سے وصول کرے گا) اور اگر وہ سب جدا جدا ہو جائیں اور پہلا بائع جا چکا ہو (اور اس کے جانے کے بعد دوسرا بائع یعنی شریک کرنے والا شخص شریک ہونے والے کے ساتھ یہی شرط لگائے کہ مال ضائع ہونے کی صورت میں تم بائع اول سے (اپنی قیمت لینا) تو اس دوسرے بائع (شریک کرنے والے) کی شرط باطل ہے اور جواب دہی (اور ذمہ داری) اسی پر ہے۔","قَالَ مَالِكٌ فِي الرَّجُلِ يَقُولُ لِلرَّجُلِ: اشْتَرِ هَذِهِ السِّلْعَةَ بَيْنِي وَبَيْنَكَ، وَانْقُدْ عَنِّى وَأَنَا أَبِيعُهَا لَكَ: إِنَّ ذَلِكَ لَا يَصْلُحُ حِينَ قَالَ: انْقُدْ عَنِّى وَأَنَا أَبِيعُهَا لَكَ. وَإِنَّمَا ذَلِكَ سَلَفٌ يُسْلِفُهُ إِيَّاهُ، عَلَى أَنْ يَبِيعَهَا لَهُ، وَلَوْ أَنَّ تِلْكَ السِّلْعَةَ هَلَكَتْ، أَوْ فَاتَتْ أَخَذَ ذَلِكَ الرَّجُلُ الَّذِي نَقَدَ الثَّمَنَ مِنْ شَرِيكِهِ مَا نَقَدَ عَنْهُ، فَهَذَا مِنَ السَّلَفِ الَّذِى يَجُرُّ مَنْفَعَةً.","امام مالک رحمہ اللہ نے اس شخص کے متعلق فرمایا جو دوسرے شخص سے کہتا ہے کہ اس (فلاں) سامان کو میرے اور اپنے درمیان (نصف نصف کر کے) خرید لو اور میری طرف سے بھی نقد (تم ہی) ادا کر دو اور میں (ابھی یا بعد میں) اسے تمھارے لیے بیچ دوں گا (اور تمھارا قرض اتار دوں گا، تو امام مالک رحمہ اللہ نے فرمایا:) بلاشبہ یہ درست (اور جائز) نہیں ہے جس وقت کہ اس نے یہ (واضح طور پر) کہہ دیا ہو کہ میری طرف سے نقد قیمت ادا کر دو اور میں تمھارے لیے اسے بیچ ڈالوں گا اور بلاشبہ یہ تو ادھار (اور قرض) ہے جسے (دوسرا آدمی) اس شرط پر دے رہا ہے کہ وہ اس سامان کو اس کے لیے (خادم بن کر) بیچے گا اور (اس کے قرض ہونے کی دلیل یہ ہے کہ) اگر وہ سامان تلف ہو جاتا یا فوت ہو جاتا (ہاتھ سے نکل جاتا) تو یہ شخص جس نے نقد قیمت ادا کی تھی، اپنے شریک سے وہ رقم وصول کر لیتا جو اس نے اس کی طرف سے نقد ادا کی تھی، لہذا یہ ایسا ادھار (اور قرض کی صورت) ہے جو منفعت کو کھینچ رہا ہے۔ (یعنی اس قرض پر نفع مل رہا ہے)","اور یہ اصول ہے کہ «كُلُّ قَرْضٍ جَرَّ مَنْفَعَةً فَهُوَ رِبًا» ہر وہ قرض جو کسی بھی (زائد) نفع کا باعث بنے تو وہ سود ہے۔ ایک روایت میں یہ الفاظ نبی اکرم صلی اللہ علیہ وسلم کی طرف نسبت کیے گئے ہیں لیکن اس کی سند ثابت نہیں ہے۔ (ارواء الغلیل: ۱۳۹۸، ضعیف الجامع الصغیر: ۴۲۴۴، اس کی سند میں سوار بن مصعب متروک راوی ہے البتہ یہ اصول دوسری صحیح روایات سے ماخوذ ہے، مثلاً دیکھیے بخاری: ۳۸۱۴۔۔۔۔۔ اور یہاں بیچ ہونے سے قبل اس نے قرض مانگا اور ساتھ ہی اس قرض کی بات کرتے وقت نفع کی صورت میں اپنی خدمت کا تذکرہ بھی کر دیا کہ میں تمھاری طرف سے اسے بیچوں گا، لہذا یہ سود ہے۔","قَالَ مَالِكٌ: وَلَوْ أَنَّ رَجُلًا ابْتَاعَ سِلْعَةً، فَوَجَبَتْ لَهُ، ثُمَّ قَالَ لَهُ رَجُلٌ: أَشْرِكْنِي بِنِصْفِ هَذِهِ السِّلْعَةِ وَأَنَا أَبِيعُهَا لَكَ جَمِيعاً.","امام مالک رحمہ اللہ نے فرمایا: اور اگر کسی آدمی نے کوئی سامان خرید لیا ہو اور وہ اس کے لیے واجب (ثابت) ہو چکا ہو، پھر اس سے کوئی آدمی کہے کہ مجھے اس سامان کے نصف كَانَ ذَلِكَ حَلَالاً لَا بَأْسَ بِهِ. وَتَفْسِيرُ ذَلِكَ: أَنَّ هَذَا بَيْعٌ جَدِيدٌ بَاعَهُ نِصْفَ السِّلْعَةِ، عَلَى أَنْ يَبِيعَ لَهُ النِّصْفَ الْآخَرَ.","میں اپنا شریک بنا لو اور میں تمھارے لیے اس سارے سامان کو بیچ دوں گا تو یہ معاملہ حلال ہے، اس میں کوئی حرج نہیں ہے۔ اور اس کی وضاحت یہ ہے کہ بلاشبہ یہ ایک نئی بیع ہے جس میں آدمی نے اس شریک کو اپنا نصف سامان اس شرط پر بیچا کہ وہ شریک اس کے لیے دوسرا نصف فروخت کرے گا۔","امام مالک رحمہ اللہ کے نزدیک اس صورت میں از سر نو نصف حصہ بیچا جا رہا ہے اور نصف حصہ اجرت پر دیا جا رہا ہے، یہ بیع اور اجارہ اکٹھے ہو رہے ہیں، لہذا یہ جائز ہیں، لیکن جمہور کے نزدیک یہ صورت بھی ممنوع ہے کیونکہ (۱) اگر سامان والے نے نصف حصہ بیچا ہوتا اور باقی نصف حصہ بیچنے کے لیے اجرت پر دیا ہوتا تو اس کی اجرت مقرر کرتا جبکہ یہاں ایسا نہیں ہے، لہذا یہ بھی نصف حصہ ادھار لے کر باقی نصف کو بیچنے کی بات کرنا دراصل ادھار پر زائد نفع کا حصول ہے۔ (۲) اگر یہ واقعی بیع اور اجارہ ہے تو پھر قیمت اور اجرت دونوں کی مقدار مجہول کیوں ہے اور (۳) اجارہ بذات خود ایک بیع ہے اور ایک بیع میں دو بیع کرنا بھی تو حرام ہی ہے۔"],"481":["§خلاصۃ الباب","اس باب میں دو مرفوع روایات (احادیث نبویہ) ہیں جو بخاری ومسلم میں بھی موجود ہیں، نیز امام مالک رحمہ اللہ کے چھ فتاویٰ بھی مذکور ہیں۔","لغوی طور پر افلاس اس حالت کو کہتے ہیں جس میں آدمی کے پاس نہ کوئی نقدی ہو اور نہ کوئی سامان اور اصطلاحاً افلاس وہ حالت ہے کہ جس میں آدمی کے پاس اس قدر مال نہ رہے جس سے قرضوں کی ادائیگی ہو سکے۔ اس کو دیوالیہ ہو جانا کہتے ہیں۔ ایسے شخص کا مال سرکار اور حکومت اپنی تحویل میں لے کر قرض خواہوں کے قرضوں کے تناسب سے ان میں تقسیم کر دیتی ہے اور پھر اس آدمی کو زندگی گزارنے کے لیے بیت المال سے تعاون مہیا کیا جاتا ہے۔"],"482":["§خلاصۃ الباب","اس باب میں دو روایات ہیں، ایک مرفوع (حدیث نبوی) ہے جو کہ صحیح مسلم میں بھی موجود ہے اور ایک موقوف (اثر صحابی) ہے جو کہ سنداً صحیح ہے، نیز امام مالک رحمہ اللہ کے دو فتاویٰ بھی مذکور ہیں۔"],"483":["§خلاصۃ الباب","اس باب میں چار موقوف روایات (آثار صحابہ) ہیں جن میں سے ایک صحیح اور تین ضعیف ہیں، نیز اس باب میں امام مالک رحمہ اللہ کا ایک فتویٰ بھی مذکور ہے۔"],"484":["§خلاصۃ الباب","اس باب میں تین احادیث نبویہ ہیں جو کہ بخاری و مسلم میں بھی ہیں، نیز امام مالک رحمہ اللہ کے تین فتاویٰ بھی مذکور ہیں۔"],"485":["§خلاصۃ الباب","اس باب میں چار روایات ہیں جن میں سے ایک مرفوع (حدیث نبوی) ہے جو بخاری ومسلم میں بھی ہے اور باقی تین مقطوع (آثار تابعین) ہیں اور وہ بھی سنداً صحیح ثابت ہیں، نیز امام مالک رحمہ اللہ کے چار فتاویٰ بھی مذکور ہیں۔"],"486":["§کتاب کا تعارف","اس کتاب میں پندرہ ابواب ہیں اور پہلے باب میں دو موقوف روایات یعنی آثار صحابہ ہیں جن میں سے ایک کی سند صحیح اور ایک کی حسن ہے۔ باقی چودہ ابواب امام مالک رحمہ اللہ کے ۴۳ فتاویٰ جات پر مشتمل ہیں۔","اہل حجاز کے ہاں قراض یا مقارضہ جبکہ اہل عراق کے ہاں اسے مضاربہ کہتے ہیں، ہمارے ہاں بھی اسے مضاربت ہی کہا جاتا ہے، اس کا مطلب یہ ہے کہ ایک شخص کا مال ہو اور دوسرے کی محنت ہو اور نفع دونوں میں مشترک ہو۔","§خلاصۃ الباب","اس باب میں دو موقوف روایات ہیں جن میں سے ایک سنداً صحیح اور دوسری حسن ہے۔"],"487":["§خلاصۃ الباب","اس باب میں امام مالک رحمہ اللہ کے چار فتاویٰ جات مذکور ہیں۔","مضاربت میں دی جانے والی رقم کو ’’راس المال‘‘ کہتے ہیں۔ یہ رقم دینے والا شخص ’’رب المال‘‘ کہلاتا ہے جبکہ مضاربت کے طور پر کام کرنے والا شخص ’’مضارب یا عامل‘‘ کہلاتا ہے، اس پوری کتاب میں یہ الفاظ بار بار استعمال ہوں گے۔","قَالَ مَالِكٌ: وَجْهُ الْقِرَاضِ الْمَعْرُوفِ الْجَائِزِ:","امام مالک رحمہ اللہ نے فرمایا: (لوگوں میں) معروف اور جائز أَنْ يَأْخُذَ الرَّجُلُ الْمَالَ مِنْ صَاحِبِهِ، عَلَى أَنْ يَعْمَلَ فِيهِ وَلَا ضَمَانَ عَلَيْهِ، وَنَفَقَةُ الْعَامِلِ فِي الْمَالِ فِي سَفَرِهِ، مِنْ طَعَامِهِ وَكِسْوَتِهِ وَمَا يُصْلِحُهُ بِالْمَعْرُوفِ، بِقَدْرِ الْمَالِ إِذَا شَخَصَ فِي الْمَالِ، إِذَا كَانَ الْمَالُ يَحْمِلُ ذَلِكَ، فَإِنْ كَانَ مُقِيماً فِي أَهْلِهِ، فَلَا نَفَقَةَ لَهُ مِنَ الْمَالِ وَلَا كِسْوَةَ.","مضاربت کی صورت یہ ہے کہ آدمی اپنے ساتھی سے اس شرط پر مال لے کہ وہ اس میں محنت کرے گا اور (لیکن) اس پر کوئی ضمانت نہ ہوگی (یعنی مال ضائع ہو جائے تو اس کی چٹی عامل پر نہیں پڑے گی) اور عامل (مضاربت پر مال لینے والے) کا اپنے سفر میں خرچہ مال ہی میں سے ہوگا یعنی اس کا کھانا پینا اور کپڑے پہننا جو دستور کے مطابق اس کی اصلاح کرے (یعنی جس کا استعمال میں لانا ضروری ہو) مال کی مقدار کے حساب سے (یہ خرچے اصل زر میں سے شمار کر لے، بشرطیکہ) جب وہ مال ہی کے سلسلے میں سفر کرے اور جب وہ مال اس کا بوجھ اٹھانے کی قدرت رکھتا ہو، چنانچہ اگر عامل اپنے ہی گھر میں مقیم ہو تو پھر اصل مال میں سے نہ اس کے لیے نان نفقہ ہوگا اور نہ کوئی کپڑا۔","قَالَ مَالِكٌ: وَلَا بَأْسَ بِأَنْ يُعِينَ الْمُتَقَارِضَانِ كُلُّ وَاحِدٍ مِنْهُمَا صَاحِبَهُ عَلَى وَجْهِ الْمَعْرُوفِ، إِذَا صَحَّ ذَلِكَ مِنْهُمَا.","امام مالک رحمہ اللہ نے فرمایا: اس میں کوئی حرج نہیں کہ مضاربت کرنے والے دونوں شخصوں (رب المال اور مضارب) میں سے ہر شخص اپنے ساتھی کا معروف طریقے کے مطابق تعاون کرے، جب وہ (تعاون کرنا) ان کی طرف سے صحیح ہو۔","یعنی کوئی سود والی شکل شامل نہ کریں اور کوئی ایسی شرط نہ لگائیں جس میں صرف کسی ایک ہی کو نفع ملتا ہو، تو اسی صورت میں باہمی تعاون درست ہے۔","قَالَ مَالِكٌ: وَلَا بَأْسَ بِأَنْ يَشْتَرِيَ رَبُّ الْمَالِ مِمَّنْ قَارَضَهُ بَعْضَ مَا يَشْتَرِي مِنَ السِّلَعِ، إِذَا كَانَ ذَلِكَ صَحِيحاً عَلَى غَيْرِ شَرْطٍ.","امام مالک رحمہ اللہ نے فرمایا: اس میں کوئی حرج نہیں کہ رب المال اس شخص کہ جس کے ساتھ اس نے مضاربت کی ہو، سے سامانوں میں سے کوئی ایسی چیز خرید لے جس کی خرید و فروخت ہوتی ہے (بشرطیکہ) جب یہ (خریداری) صحیح ہو اور بغیر شرط کے ہو۔","مضارب نے رقم لے کر کاروبار ہی کرنا ہے، سامان خریدنا اور اسے بیچنا ہے، چنانچہ اگر اسی سامان میں سے کوئی چیز رب المال بھی خرید لے تو درست ہے بشرطیکہ عقد مضاربت اور معاملہ طے کرنے کے دوران خریدنے کی شرط نہ لگائی گئی ہو۔","قَالَ مَالِكٌ فِيمَنْ دَفَعَ إِلَى رَجُلٍ وَإِلَى غُلَامٍ لَهُ مَالاً قِرَاضاً يَعْمَلَانِ فِيهِ جَمِيعاً: إِنَّ ذَلِكَ جَائِزٌ لَا بَأْسَ بِهِ، لِأَنَّ الرِّبْحَ مَالٌ لِغُلَامِهِ، لَا يَكُونُ الرِّبْحُ لِلسَّيِّدِ حَتَّى يَنْتَزِعَهُ مِنْهُ، وَهُوَ بِمَنْزِلَةِ غَيْرِهِ مِنْ كَسْبِهِ.","امام مالک رحمہ اللہ نے اس شخص کے متعلق فرمایا جو ایک آدمی (عامل) کو اور اپنے ہی ایک غلام کو بطور مضاربت مال دے دیتا ہے جس میں وہ دونوں اکٹھے کام کریں گے تو بلاشبہ یہ بھی جائز ہے، اس میں کوئی حرج نہیں ہے، کیونکہ (حاصل شدہ) نفع غلام کا مال ہوگا، وہ نفع اس کے آقا کو نہیں ملے گا کہ وہ اسے اس کے ہاتھ سے چھین لے اور وہ نفع غلام کی اس کے علاوہ دوسری کمائی کی طرح ہوگا۔","سوال یہ پیدا ہوتا تھا کہ جب رب المال ایک عامل کو اپنے غلام سمیت مال مضاربت دے گا، پھر جو نفع اس عامل اور غلام کو مشترکہ طور پر ملے گا اور اسے وہ باہم تقسیم کریں گے تو کیا اس غلام کا یہ نفع اس کے آقا ہی کی ملکیت شمار ہوگا یا غلام کی ملکیت؟ اگر تو وہ آقا کی ملکیت شمار ہو تو پھر یہ خرابی لازم آئے گی کہ آقا نے کل نفع میں سے بھی نصف حصہ رکھ لیا اور باقی نصف میں سے جو غلام کو حصہ ملا تھا اسے بھی وصول کر لیا تو گو آقا نے تین حصے نفع کمایا اور عامل نے ایک حصہ، تو کیا یہ درست ہے؟ تو امام مالک رحمہ اللہ نے فرمایا کہ یہ غلام کا حصہ غلام ہی کی ملکیت رہے گا اور راجح موقف بھی یہی ہے کہ غلام اپنے آقا کی طرف سے مقرر کردہ مزدوری کے علاوہ جو کچھ کماتا ہے وہ غلام ہی کی ملکیت شمار ہوتا ہے نہ کہ آقا کی۔"]})